test("破势：多层破势叠加并在下一次主动突袭一次性消耗", async () => {
  const a = makePlayer("a", 0, "dawn"), b = makePlayer("b", 1, "dusk");
  b.hp = 8;
  b.maxHp = 8;
  const { game }
    = makeGame([a, b]);
  for (let i = 0; i < 2; i += 1) {
    const c = instance("exposeWeakness");
    a.hand.push(c);
    await game.playCard(a, c, []);
  }
  assert.equal(a.statuses.exposeWeakness.stacks, 2);
  const attack = instance("assault");
  a.hand.push(attack);
  await game.playCard(a, attack, [b]);
  assert.equal(b.hp, 5);
  assert.equal(a.statuses.exposeWeakness, undefined);
});

