test("回收站：每回合前两张战术各摸1且被反制也触发", async () => {
  const a = makePlayer("a", 0, "dawn"), b = makePlayer("b", 1, "dusk", "human");
  const { game }
    = makeGame([a, b], { response: (request) => request.type === "counter" });
  const drawReasons = [];
  game.eventDispatcher.on("afterCardMove", "test:recycle-standard-draw", (event) => {
    if (event.from === "deck" && event.to === "hand") drawReasons.push(event.reason);
  });
  a.equipment = instance("recycleDevice");
  a.hand.push(instance("harvest"), instance("exposeWeakness"), instance("exposeWeakness"));
  b.hand.push(instance("counter"));
  game.state.deck.cards.push(instance("charge"), instance("block"), instance("shield"));
  await game.playCard(a, a.hand[0], []);
  await game.playCard(a, a.hand[0], []);
  await game.playCard(a, a.hand[0], []);
  assert.equal(a.turnFlags.recycleDeviceUses, 2);
  assert.equal(a.hand.length, 2);
  assert.deepEqual(drawReasons, ["回收站", "回收站"]);
  assert.deepEqual(
    game.state.logs.filter((entry) => entry.message.includes("的「回收站」触发")).map((entry) => entry.message),
    [
      `${a.name}的「回收站」触发（1/2），摸1张牌。`,
      `${a.name}的「回收站」触发（2/2），摸1张牌。`
    ]
  );
});

test("回收站：次数只在装备区显示并随 global-turn 状态重置", () => {
  const player = makePlayer("recycle-ui", 0, "dawn", "human");
  player.equipment = instance("recycleDevice");
  for (const uses of [0, 1, 2]) {
    player.turnFlags.recycleDeviceUses = uses;
    const equipment = equipmentSlotTemplate(player, true),
      panel = playerPanelTemplate(player, { isHuman: true });
    assert.match(equipment, new RegExp(`>${uses}/2<`));
    const status = panel.match(/<span class="panel-status"[\s\S]*?<\/span>/)?.[0] ?? "";
    assert.doesNotMatch(status, /回收站|回收|\d\/2/);
  }
  player.resetGlobalTurnReactiveFlags(TEST_VERSION_STATE);
  assert.match(equipmentSlotTemplate(player, true), />0\/2</);
  player.equipment = null;
  assert.doesNotMatch(equipmentSlotTemplate(player, true), />\d\/2</);
});

