test("影客：窥隙真人选择只私下展示且公共日志与DOM不泄露牌面", async () => {
  const shade = makePlayer("peek-human", 0, "dawn", "human", 3),
    target = makePlayer("peek-target", 1, "dusk"),
    secrets = [instance("counter"), instance("harvest"), instance("duel")];
  target.hand.push(...secrets);
  const { game, ui }
    = makeGame([shade, target]);
  registerPassiveSkills(game);
  await game.damage(shade, target, 1, { canBlock: false });
  assert.equal(ui.hiddenRequests.length, 1);
  const request = ui.hiddenRequests[0], markup = hiddenSelectionMarkup(request.selection);
  assert.equal("helpText" in request.options, false);
  assert.equal("hideHelpText" in request.options, false);
  for (const card of secrets) {
    assert.doesNotMatch(markup, new RegExp(card.id));
    assert.doesNotMatch(markup, new RegExp(card.definitionId));
    assert.doesNotMatch(markup, new RegExp(card.name));
    assert.doesNotMatch(markup, new RegExp(card.description));
  }
  assert.deepEqual(ui.reveals[0].cards, secrets.slice(0, 2));
  assert.equal(game.hiddenCardSelection.sessions.size, 0);
  assert.equal(game.hiddenCardSelection.selections.size, 0);
  const publicLog = game.state.logs.find((entry) => entry.message.includes("触发「窥隙」"));
  assert.equal(publicLog.message, `${shade.name}触发「窥隙」，查看了${target.name}的2张手牌。`);
  for (const card of secrets) assert.doesNotMatch(publicLog.message, new RegExp(card.name));
});

