test("炎术师：余烬每个卡牌结算ID最多触发1次", async () => {
  const ember = makePlayer("ember", 0, "dawn", "ai", 4),
    enemyA = makePlayer("enemy-a", 1, "dusk"),
    enemyB = makePlayer("enemy-b", 2, "dusk");
  const { game }
    = makeGame([ember, enemyA, enemyB]);
  registerPassiveSkills(game);
  ember.energy = 0;
  const card = instance("shockwave");
  await game.eventDispatcher.emit(
    "afterDamage", { source: ember, target: enemyA, actualAmount: 1, card, resolutionId: "same" }
  );
  await game.eventDispatcher.emit(
    "afterDamage", { source: ember, target: enemyB, actualAmount: 1, card, resolutionId: "same" }
  );
  assert.equal(ember.energy, 1);
  await game.eventDispatcher.emit(
    "afterDamage", { source: ember, target: enemyB, actualAmount: 1, card, resolutionId: "next" }
  );
  assert.equal(ember.energy, 2);
  assert.deepEqual(
    game.state.logs.filter((entry) => entry.message.includes("「余烬」")).map((entry) => entry.message),
    [
      `${ember.name}触发「余烬」，获得1点能量。`,
      `${ember.name}触发「余烬」，获得1点能量。`
    ]
  );
  assert.ok(!game.state.logs.some((entry) => entry.message.includes("通过余烬")));
});

test("炎术师：焚场对1、2、3名存活敌人固定消耗3点能量，2点非法、3点合法并扣至0", async () => {
  for (const enemyCount of [1, 2, 3]) {
    const ember = makePlayer(`ember-cost-${enemyCount}`, 0, "dawn", "human", 4),
      ally = makePlayer(`ember-cost-ally-${enemyCount}`, 1, "dawn", "ai", 0),
      enemies = Array.from(
        { length: enemyCount },
        (_, index) => makePlayer(`ember-cost-enemy-${enemyCount}-${index}`, index + 2, "dusk", "ai", 5)
      );
    const { game } = makeGame([ember, ally, ...enemies]);
    assert.equal(getActiveSkillCost(game, ember, ACTIVE_SKILLS.burningField), 3);
    ember.energy = 2;
    assert.equal(canUseSkill(game, ember, ACTIVE_SKILLS.burningField).ok, false);
    assert.equal(await game.useActiveSkill(ember, "burningField", []), false);
    assert.equal(ember.energy, 2);
    assert.equal(ember.turnFlags.activeSkillUseCounts.burningField ?? 0, 0);
    const hpBefore = enemies.map((enemy) => enemy.hp);
    ember.energy = 3;
    assert.equal(canUseSkill(game, ember, ACTIVE_SKILLS.burningField).ok, true);
    assert.equal(await game.useActiveSkill(ember, "burningField", []), true);
    assert.equal(ember.energy, 0);
    assert.equal(ember.turnFlags.activeSkillUseCounts.burningField, 1);
    assert.deepEqual(enemies.map((enemy) => enemy.hp), hpBefore.map((hp) => hp - 1));
  }
});

test("炎术师：焚场只伤害存活敌人、队友与本人不受伤且伤害可格挡", async () => {
  const ember = makePlayer("ember-field", 0, "dawn", "human", 4);
  const ally = makePlayer("ember-field-ally", 1, "dawn", "ai", 0);
  const deadEnemy = makePlayer("ember-field-dead", 2, "dusk", "ai", 5);
  const enemyA = makePlayer("ember-field-enemy-a", 3, "dusk", "ai", 5);
  const enemyB = makePlayer("ember-field-enemy-b", 4, "dusk", "ai", 5);
  deadEnemy.alive = false;
  ember.energy = 3;
  let observed = null;
  const { game }
    = makeGame([ember, ally, deadEnemy, enemyA, enemyB]);
  assert.equal(getActiveSkillCost(game, ember, ACTIVE_SKILLS.burningField), 3);
  game.eventDispatcher.on("beforeDamage", "test:burning-field-options", (event) => {
    observed = { canBlock: event.canBlock, damageType: event.damageType, skill: event.skill };
  });
  const allyHp = ally.hp, emberHp = ember.hp, deadHp = deadEnemy.hp;
  const hpA = enemyA.hp, hpB = enemyB.hp;
  assert.equal(await game.useActiveSkill(ember, "burningField", []), true);
  assert.equal(enemyA.hp, hpA - 1);
  assert.equal(enemyB.hp, hpB - 1);
  assert.equal(ally.hp, allyHp);
  assert.equal(ember.hp, emberHp);
  assert.equal(deadEnemy.hp, deadHp);
  assert.ok(observed);
  assert.equal(observed.canBlock, true);
  assert.equal(observed.damageType, "skill");
  assert.equal(observed.skill, "burningField");
});

test("炎术师：焚场仅为有格挡目标创建响应且不影响其他目标", async () => {
  const ember = makePlayer("ember-block-field", 0, "dawn", "human", 4),
    ally = makePlayer("ember-block-ally", 1, "dawn", "ai", 0),
    blocker = makePlayer("ember-blocker", 2, "dusk", "human", 5),
    open = makePlayer("ember-open", 3, "dusk", "human", 5);
  blocker.hand.push(instance("block"));
  ember.energy = 3;
  const { game, ui } = makeGame([ember, ally, blocker, open], {
    response: (request) => request.type === "block" && request.targetPlayerId === blocker.id
  });
  const allyHp = ally.hp, blockerHp = blocker.hp, openHp = open.hp;
  assert.equal(await game.useActiveSkill(ember, "burningField", []), true);
  const blockRequests = ui.responseRequests.filter((entry) => entry.type === "block");
  assert.equal(blockRequests.length, 1);
  assert.deepEqual(
    blockRequests.map((entry) => entry.targetPlayerId),
    [blocker.id]
  );
  assert.equal(blocker.hp, blockerHp);
  assert.equal(blocker.hand.length, 0);
  assert.equal(open.hp, openHp - 1);
  assert.equal(ally.hp, allyHp);
  assert.equal(ember.hp, ember.maxHp);
});

test("炎术师：焚场先结算格挡且被格挡目标不消耗护援", async () => {
  const ember = makePlayer("ember-order", 0, "dusk", "ai", 4),
    blocker = makePlayer("order-blocker", 1, "dawn", "human", 5),
    guardian = makePlayer("order-guardian", 2, "dawn", "human", 1),
    open = makePlayer("order-open", 3, "dawn", "human", 5);
  blocker.hand.push(instance("block"));
  guardian.hand.push(instance("charge"));
  ember.energy = 3;
  const order = [];
  const { game } = makeGame([ember, blocker, guardian, open], {
    response: (request) => {
      if (request.type === "block") {
        order.push(`block:${request.targetPlayerId}`);
        return request.targetPlayerId === blocker.id;
      }
      if (request.type === "skill") {
        order.push(`aid:${request.targetPlayerId}`);
        return false;
      }
      return false;
    }
  });
  registerPassiveSkills(game);
  const blockerHp = blocker.hp, openHp = open.hp, guardianHand = guardian.hand.length;
  assert.equal(await game.useActiveSkill(ember, "burningField", []), true);
  assert.equal(blocker.hp, blockerHp);
  assert.equal(open.hp, openHp - 1);
  assert.equal(guardian.hand.length, guardianHand);
  assert.equal(guardian.turnFlags.guardianAidUsed, false);
  const aidRequests = order.filter((entry) => entry.startsWith("aid:"));
  assert.equal(aidRequests.length, 1, "只有未格挡目标触发护援响应");
  assert.equal(aidRequests[0], `aid:${open.id}`);
  assert.ok(order.indexOf(`aid:${open.id}`) > order.indexOf(`block:${open.id}`));
});

test("炎术师：焚场每回合最多发动两次且第三次不扣费不造成伤害", async () => {
  const ember = makePlayer("ember-limit", 0, "dawn", "human", 4);
  const ally = makePlayer("ember-limit-ally", 1, "dawn", "ai", 0);
  const enemy = makePlayer("ember-limit-enemy", 2, "dusk", "ai", 5);
  ember.energy = 4;
  const { game }
    = makeGame([ember, ally, enemy]);
  const hp = enemy.hp;
  const emberConfig = presentCharacter("ember-magus");
  assert.equal(emberConfig.activeLimitPerTurn, 2);
  assert.equal(ACTIVE_SKILLS.burningField.limitPerTurn, 2);
  assert.equal(emberConfig.activeCost, 3);
  assert.equal(ACTIVE_SKILLS.burningField.cost, 3);
  assert.equal(await game.useActiveSkill(ember, "burningField", []), true);
  assert.equal(ember.energy, 1);
  assert.equal(enemy.hp, hp - 1);
  assert.equal(ember.turnFlags.activeSkillUseCounts.burningField, 1);
  assert.equal(await game.useActiveSkill(ember, "burningField", []), false);
  assert.equal(ember.energy, 1);
  assert.equal(enemy.hp, hp - 1);
  assert.equal(ember.turnFlags.activeSkillUseCounts.burningField, 1);
  ember.energy = 4;
  assert.equal(await game.useActiveSkill(ember, "burningField", []), true);
  assert.equal(ember.energy, 1);
  assert.equal(enemy.hp, hp - 2);
  assert.equal(ember.turnFlags.activeSkillUseCounts.burningField, 2);
  ember.energy = 4;
  assert.equal(canUseSkill(game, ember, ACTIVE_SKILLS.burningField).ok, false);
  assert.equal(await game.useActiveSkill(ember, "burningField", []), false);
  assert.equal(ember.energy, 4);
  assert.equal(enemy.hp, hp - 2);
  assert.equal(ember.turnFlags.activeSkillUseCounts.burningField, 2);
});

test("炎术师：余烬按挑衅和震荡的同一resolutionId各只触发一次", async () => {
  for (const definitionId of ["provoke", "shockwave"]) {
    const ember = makePlayer(`ember-${definitionId}`, 0, "dawn", "ai", 4),
      enemies = [1, 2, 3].map((seat) => makePlayer(`${definitionId}-enemy-${seat}`, seat, "dusk"));
    const { game }
      = makeGame([ember, ...enemies]);
    registerPassiveSkills(game);
    ember.energy = 0;
    ember.hand.push(instance(definitionId));
    await game.playCard(ember, ember.hand[0], enemies);
    assert.equal(ember.energy, 1);
  }
  const ember = makePlayer("ember-two-cards", 0, "dawn", "ai", 4),
    enemy = makePlayer("ember-two-target", 1, "dusk"),
    { game }
      = makeGame([ember, enemy]);
  registerPassiveSkills(game);
  ember.energy = 0;
  ember.hand.push(instance("provoke"), instance("provoke"));
  await game.playCard(ember, ember.hand[0], [enemy]);
  await game.playCard(ember, ember.hand[0], [enemy]);
  assert.equal(ember.energy, 2);
});

