test("赌命者：孤注按实际消耗能量摸E-1张并以每点25%概率进入状态", async () => {
  const cases = [
    [1, .249, true], [1, .25, false],
    [2, .499, true], [2, .5, false],
    [3, .749, true], [3, .75, false],
    [4, .999, true], [5, .999, true]
  ];
  for (const [energy, roll, expected] of cases) {
    const gambler = makePlayer(`gambler-${energy}-${roll}`, 0, "dawn", "ai", 6),
      enemy = makePlayer(`enemy-${energy}-${roll}`, 1, "dusk");
    const { game }
      = makeGame([gambler, enemy], { random: () => roll });
    const drawReasons = [];
    game.eventDispatcher.on("afterCardMove", `test:all-in-standard-draw:${energy}:${roll}`, (event) => {
      if (event.from === "deck" && event.to === "hand") drawReasons.push(event.reason);
    });
    registerPassiveSkills(game);
    const drawCount = Math.max(0, energy - 1);
    game.state.deck.cards.push(...Array.from({ length: drawCount }, () => instance("charge")));
    gambler.energy = energy;
    assert.equal(await game.useActiveSkill(gambler, "allIn", []), true);
    assert.equal(gambler.energy, 0);
    assert.equal(gambler.hand.length, drawCount);
    assert.deepEqual(drawReasons, Array.from({ length: drawCount }, () => "孤注"));
    assert.equal(Boolean(gambler.statuses.allIn), expected, `${energy}点能量，随机数${roll}`);
    const allInLogs = game.state.logs.filter(
      (entry) => entry.message.startsWith(gambler.name) && entry.message.includes("发动「孤注」")
    );
    assert.equal(allInLogs.length, 1);
    assert.doesNotMatch(allInLogs[0].message, /%/);
    assert.equal(game.state.logs.filter((entry) => entry.message.includes(`${gambler.name}摸了`)).length, 0);
    gambler.energy = 1;
    assert.equal(await game.useActiveSkill(gambler, "allIn", []), false, "一回合只能使用1次");
    assert.deepEqual(
      canUseSkill(game, gambler, ACTIVE_SKILLS.allIn), { ok: false, reason: "本回合发动次数已用尽" }, "同回合拒绝原因必须是每回合次数限制"
    );
  }
});

test("赌命者：未处于孤注时突袭命中、格挡或雷达免疫均不记录退出日志", async () => {
  const run = async (result) => {
    const gambler = makePlayer(`no-all-in-${result}-gambler`, 0, "dawn", "ai", 6),
      target = makePlayer(`no-all-in-${result}-target`, 1, "dusk", result === "block" ? "human" : "ai", 3),
      assault = instance("assault"),
      { game } = makeGame([gambler, target], { response: () => true });
    registerPassiveSkills(game);
    gambler.hand.push(assault);
    if (result === "block") target.hand.push(instance("block"));
    if (result === "radar") {
      target.equipment = instance("defenseDevice");
      game.state.deck.cards.push(instance("harvest"));
    }
    const hp = target.hp;
    assert.equal(gambler.statuses.allIn, undefined);
    assert.equal(await game.playCard(gambler, assault, [target]), true);
    assert.equal(target.hp, result === "normal" ? hp - 1 : hp);
    assert.equal(gambler.statuses.allIn, undefined);
    assert.equal(
      game.state.logs.filter((entry) => entry.message === `${gambler.name}退出「孤注」状态。`).length,
      0
    );
  };

  for (const result of ["normal", "block", "radar"]) await run(result);
});

