// ---- 原子响应支付 ----

test("原子响应：两张响应牌原子支付成功时统一提交并发送完整移动事件", async () => {
  const player = makePlayer("atomic-success", 0, "dawn"),
    enemy = makePlayer("atomic-success-enemy", 1, "dusk"),
    first = instance("block"),
    second = instance("block");
  player.hand.push(first, second);
  const { game }
    = makeGame([player, enemy]), events = [];
  game.eventDispatcher.on("afterCardMove", "test:atomic-success", (event) => events.push(event.card));
  const beforeVersion = player.handVersion,
    result = await game.payCardsFromHandAtomically(
      player, [first, second], "测试原子支付", { silent: true, expectedCount: 2 }
    );
  assert.equal(result.status, "used");
  assert.deepEqual(result.cards, [first, second]);
  assert.equal(player.hand.length, 0);
  assert.equal(player.handVersion, beforeVersion + 1);
  assert.ok(game.state.deck.discardPile.includes(first));
  assert.ok(game.state.deck.discardPile.includes(second));
  assert.deepEqual(events, [first, second]);
});

test("原子响应：第二张 beforeCardMove 取消时原子响应两张牌都保留", async () => {
  const player = makePlayer("atomic-cancel", 0, "dawn"),
    enemy = makePlayer("atomic-cancel-enemy", 1, "dusk"),
    first = instance("block"),
    second = instance("block");
  player.hand.push(first, second);
  const { game }
    = makeGame([player, enemy]);
  game.eventDispatcher.on("beforeCardMove", "test:atomic-cancel", (event) => {
    if (event.card === second) event.cancelled = true;
  });
  const version = player.handVersion,
    result = await game.payCardsFromHandAtomically(
      player, [first, second], "测试原子取消", { silent: true, expectedCount: 2 }
    );
  assert.equal(result.status, "invalid");
  assert.deepEqual(player.hand, [first, second]);
  assert.equal(player.handVersion, version);
  assert.equal(game.state.deck.discardPile.includes(first), false);
  assert.equal(game.state.deck.discardPile.includes(second), false);
});

test("原子响应：支付拒绝已离手实体和重复实体且不移动其余牌", async () => {
  const player = makePlayer("atomic-invalid", 0, "dawn"),
    enemy = makePlayer("atomic-invalid-enemy", 1, "dusk"),
    first = instance("block"),
    second = instance("block");
  player.hand.push(first, second);
  const { game }
    = makeGame([player, enemy]);
  player.hand.splice(player.hand.indexOf(second), 1);
  const missing = await game.payCardsFromHandAtomically(
    player, [first, second], "测试实体已变化", { silent: true, expectedCount: 2 }
  );
  assert.equal(missing.status, "invalid");
  assert.deepEqual(player.hand, [first]);
  assert.equal(game.state.deck.discardPile.includes(first), false);
  player.hand.push(second);
  const duplicate = await game.payCardsFromHandAtomically(
    player, [first, first], "测试重复实体", { silent: true, expectedCount: 2 }
  );
  assert.equal(duplicate.status, "invalid");
  assert.deepEqual(player.hand, [first, second]);
  assert.equal(game.state.deck.discardPile.length, 0);
});

test("原子响应：支付验证期间 dispose 返回 cancelled 且不消费任何牌", async () => {
  const player = makePlayer("atomic-dispose", 0, "dawn"),
    enemy = makePlayer("atomic-dispose-enemy", 1, "dusk"),
    first = instance("block"),
    second = instance("block");
  player.hand.push(first, second);
  const { game }
    = makeGame([player, enemy]);
  let openedResolve, release;
  const opened = new Promise((resolve) => {
    openedResolve = resolve;
  }), gate = new Promise((resolve) => { release = resolve; });
  game.eventDispatcher.on("beforeCardMove", "test:atomic-dispose", async () => {
    openedResolve();
    await gate;
  });
  const pending = game.payCardsFromHandAtomically(
    player, [first, second], "测试销毁取消", { silent: true, expectedCount: 2 }
  );
  await opened;
  game.dispose();
  release();
  const result = await pending;
  assert.equal(result.status, "cancelled");
  assert.deepEqual(player.hand, [first, second]);
  assert.equal(game.state.deck.discardPile.length, 0);
});

test("原子响应：响应系统只有整组原子支付完成后才返回 used", async () => {
  const attacker = makePlayer("atomic-response-attacker", 0, "dawn"),
    defender = makePlayer("atomic-response-defender", 1, "dusk", "human"),
    first = instance("block"),
    second = instance("block");
  defender.hand.push(first, second);
  const { game }
    = makeGame([attacker, defender], { response: () => true });
  game.eventDispatcher.on("beforeCardMove", "test:atomic-response-invalid", (event) => {
    if (event.card === second) event.cancelled = true;
  });
  const result = await game.responseWorkflow.requestCardResponse(
    defender, "block", { source: attacker, target: defender, card: instance("assault") }, 2
  );
  assert.equal(result.status, "invalid");
  assert.deepEqual(result.cards, []);
  assert.deepEqual(defender.hand, [first, second]);
  assert.equal(game.state.deck.discardPile.length, 0);
});

/*
功能
运行 FR-ARCH-1 原子响应支付与 zone 唯一性 characterization。

调用方
当前测试。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
独立 Game fixture 的 trace 与 zone occurrence。

写入状态
无生产状态。

调用函数
makePlayer、makeGame、instance、installFrArchTrace、Game.payCardsFromHandAtomically。

边界与不变量
两张支付牌必须同时离开手牌且各自只出现在弃牌堆。
*/
async function frArchAtomicZoneTrace() {
  const actor = makePlayer("fr-zone-actor", 0, "dawn", "ai", 0);
  const other = makePlayer("fr-zone-other", 1, "dusk", "ai", 1);
  const first = instance("block");
  const second = instance("block");
  actor.hand.push(first, second);
  const { game } = makeGame([actor, other]);
  const trace = installFrArchTrace(game);
  const beforeVersion = actor.handVersion;
  const payment = await game.payCardsFromHandAtomically(actor, [first, second], "FR-ARCH 原子支付", {
    silent: true,
    expectedCount: 2
  });
  assert.equal(payment.status, "used");
  assert.deepEqual(actor.hand, []);
  assert.equal(actor.handVersion, beforeVersion + 1);
  assertCardOnlyIn(game, first, "discard");
  assertCardOnlyIn(game, second, "discard");
  assert.deepEqual(trace.events, [
    "beforeCardMove",
    "beforeCardMove",
    "afterCardMove",
    "afterCardMove"
  ]);
}

test("区域不变量：原子支付与实体唯一区域冻结", frArchAtomicZoneTrace);

