/*
功能
创建含 known、anonymous 与 equipment 三类资源的 canonical World 测试夹具。

调用方
AI·资源闭合的 destroy/plunder resolved transition tests。

输入
资源拥有者是否与行动者同阵营。

输出
World、模拟行动者/拥有者、Simulator 与三类 selection descriptors。

读取状态
makeGame、合法 private-card memory 与 createInitialWorld。

写入状态
只写独立测试 Game fixture。

调用函数
deriveCurrentCardCounts、createInitialWorld、Simulator constructor。

边界与不变量
known 保留 exact ID，unknown 只保留 aggregate slot，equipment 只使用公开 definition。
*/
function createResolvedResourceFixture(sameTeam = false) {
  const actor = makePlayer("resolved-resource-actor", 0, "dawn");
  const owner = makePlayer(
    "resolved-resource-owner",
    1,
    sameTeam ? "dawn" : "dusk",
    "ai",
    2
  );
  const known = instance("recover"), unknown = instance("counter");
  owner.hand = [known, unknown];
  owner.equipment = instance("telescope");
  const { game } = makeGame([actor, owner], { random: () => 0 });
  game.rememberPrivateCard(actor, owner, known);
  const world = createInitialWorld(
    actor.id,
    game.state,
    deriveCurrentCardCounts(actor, game.state)
  );
  const simulator = new Simulator(world);
  const mutableWorld = simulator.clone(world);
  const searchActor = mutableWorld.players.find((player) => player.id === actor.id);
  const searchOwner = mutableWorld.players.find((player) => player.id === owner.id);
  const unknownCount = searchOwner.handCount - searchOwner.knownCards.length;
  return {
    world: mutableWorld,
    actor: searchActor,
    owner: searchOwner,
    simulator,
    known: {
      zone: "hand",
      selectionKind: "known",
      cardId: known.id,
      definitionId: known.definitionId,
      availableUnknownCount: 0
    },
    unknown: {
      zone: "hand",
      selectionKind: "unknown",
      cardId: null,
      definitionId: null,
      knownCardIds: [known.id],
      availableUnknownCount: unknownCount
    },
    equipment: {
      zone: "equipment",
      selectionKind: "equipment",
      cardId: null,
      definitionId: "telescope",
      availableUnknownCount: 0
    }
  };
}

test("AI·资源闭合：destroy 只执行 resolved known、anonymous、equipment 且 known 缺失不改选", () => {
  const known = createResolvedResourceFixture();
  assert.equal(known.simulator.destroyResource(
    known.world, known.actor, known.owner, 1, "resolved-destroy", known.known
  ), 1);
  assert.equal(known.owner.knownCards.some((card) => card.cardId === known.known.cardId), false);

  const anonymous = createResolvedResourceFixture();
  assert.equal(anonymous.simulator.destroyResource(
    anonymous.world, anonymous.actor, anonymous.owner, 1, "resolved-destroy", anonymous.unknown
  ), 1);
  assert.equal(anonymous.owner.knownCards.length, 1);

  const equipment = createResolvedResourceFixture();
  assert.equal(equipment.simulator.destroyResource(
    equipment.world, equipment.actor, equipment.owner, 1, "resolved-destroy", equipment.equipment
  ), 1);
  assert.equal(equipment.owner.equipmentRetentionProbability, 0);

  const missing = createResolvedResourceFixture();
  const beforeCount = missing.owner.handCount;
  assert.equal(missing.simulator.destroyResource(
    missing.world,
    missing.actor,
    missing.owner,
    1,
    "resolved-destroy",
    { ...missing.known, cardId: "missing-known-card" }
  ), 0);
  assert.equal(missing.owner.handCount, beforeCount);
  assert.equal(missing.owner.knownCards.length, 1);
});

test("AI·资源闭合：plunder 敌我来源均只转移 resolved known、anonymous、equipment", () => {
  for (const sameTeam of [false, true]) {
    for (const key of ["known", "unknown", "equipment"]) {
      const fixture = createResolvedResourceFixture(sameTeam);
      const actorBefore = fixture.actor.handCount;
      const ownerBefore = fixture.owner.handCount;
      assert.equal(fixture.simulator.takeResourceToHand(
        fixture.world,
        fixture.actor,
        fixture.owner,
        1,
        "resolved-plunder",
        fixture[key]
      ), 1, `${sameTeam ? "ally" : "enemy"}:${key}`);
      assert.equal(fixture.actor.handCount, actorBefore + 1);
      if (key === "equipment") {
        assert.equal(fixture.owner.equipmentRetentionProbability, 0);
        assert.equal(fixture.owner.handCount, ownerBefore);
      } else {
        assert.equal(fixture.owner.handCount, ownerBefore - 1);
      }
    }
  }
});

/*
功能
验证 Simulator 只执行已由 Evaluator 确定的 Block、Guardian 与 Rescue 布尔选择。

调用方
AI 核心链路测试分组。

输入
无。

输出
无；接受与拒绝世界均满足资源和生命状态断言。

读取状态
canonical Probability fixture 与 Domain response/combat rules。

写入状态
仅写每个独立测试 World。

调用函数
Simulator.consumeBlockResponseWorlds、simulateGuardianAid、resolveFatal。

边界与不变量
拒绝不得消费资源；接受只消费一次；capacity 仍由 Probability 决定，死亡清理仍由 CombatSimulation 决定。
*/
function responseWillingnessTransitionGate() {
  const blockTarget = {
    id: "closure-block-target",
    seatIndex: 0,
    battleTeam: "dawn",
    characterId: "blade-walker",
    alive: true,
    hp: 4,
    maxHp: 4,
    shield: 0,
    handCount: 1,
    hand: [{ id: "closure-block", definitionId: "block", availability: 1 }],
    knownCards: [],
    statuses: []
  };
  const acceptedBlockState = {
    remainingCardCounts: { block: 0, counter: 0, recover: 0, assault: 3 },
    players: [blockTarget]
  };
  const rejectedBlockState = structuredClone(acceptedBlockState);
  let acceptedBlockCalls = 0;
  let rejectedBlockCalls = 0;
  const attackWorlds = [{
    probability: 1,
    conditions: {},
    occurs: true,
    responseAllowed: true,
    requiredCount: 1,
    originalRequiredCount: 1
  }];
  const acceptedBlock = new Simulator(acceptedBlockState, {
    decideBlock: () => (acceptedBlockCalls += 1, true)
  }).consumeBlockResponseWorlds(acceptedBlockState, acceptedBlockState.players[0], attackWorlds);
  const rejectedBlock = new Simulator(rejectedBlockState, {
    decideBlock: () => (rejectedBlockCalls += 1, false)
  }).consumeBlockResponseWorlds(rejectedBlockState, rejectedBlockState.players[0], attackWorlds);
  assert.equal(acceptedBlock.blockedProbability, 1);
  assert.equal(acceptedBlockState.players[0].handCount, 0);
  assert.equal(rejectedBlock.blockedProbability, 0);
  assert.equal(rejectedBlockState.players[0].handCount, 1);
  assert.equal(acceptedBlockCalls, 1);
  assert.equal(rejectedBlockCalls, 1);

  const guardianState = {
    remainingCardCounts: { block: 0, counter: 0, recover: 0, assault: 3 },
    players: [
      {
        id: "closure-protected",
        seatIndex: 0,
        battleTeam: "dawn",
        characterId: "blade-walker",
        alive: true,
        hp: 3,
        maxHp: 4,
        shield: 0,
        handCount: 0,
        hand: [],
        knownCards: [],
        statuses: []
      },
      {
        id: "closure-guardian",
        seatIndex: 1,
        battleTeam: "dawn",
        characterId: "oath-warden",
        alive: true,
        hp: 4,
        maxHp: 4,
        shield: 0,
        handCount: 1,
        hand: [{ id: "closure-guardian-card", definitionId: "charge", availability: 1 }],
        knownCards: [],
        statuses: [],
        guardianAidUsed: false,
        guardianAidUsedProbability: 0
      }
    ]
  };
  const rejectedGuardianState = structuredClone(guardianState);
  let acceptedGuardianCalls = 0;
  let rejectedGuardianCalls = 0;
  let guardianSelectionCalls = 0;
  const acceptedGuardianDamage = new Simulator(guardianState, {
    decideGuardianAid: () => (acceptedGuardianCalls += 1, true),
    resolveDiscardCandidates: (player, cards, count, context) => (
      guardianSelectionCalls += 1,
      chooseDiscardCandidates(player, cards, count, context)
    )
  }).simulateGuardianAid(guardianState, guardianState.players[0], 1, 1);
  const rejectedGuardianDamage = new Simulator(rejectedGuardianState, {
    decideGuardianAid: () => (rejectedGuardianCalls += 1, false)
  }).simulateGuardianAid(rejectedGuardianState, rejectedGuardianState.players[0], 1, 1);
  assert.equal(acceptedGuardianDamage, 0);
  assert.equal(guardianState.players[1].handCount, 0);
  assert.equal(rejectedGuardianDamage, 1);
  assert.equal(rejectedGuardianState.players[1].handCount, 1);
  assert.equal(acceptedGuardianCalls, 1);
  assert.equal(rejectedGuardianCalls, 1);
  assert.equal(guardianSelectionCalls, 1);

  const rescueState = {
    remainingCardCounts: { block: 0, counter: 0, recover: 0, assault: 3 },
    players: [
      {
        id: "closure-dying",
        seatIndex: 0,
        battleTeam: "dawn",
        characterId: "blade-walker",
        alive: true,
        hp: 0,
        maxHp: 4,
        shield: 0,
        handCount: 0,
        hand: [],
        knownCards: [],
        statuses: [],
        equipmentDefinitionId: null
      },
      {
        id: "closure-rescuer",
        seatIndex: 1,
        battleTeam: "dawn",
        characterId: "blade-walker",
        alive: true,
        hp: 3,
        maxHp: 4,
        shield: 0,
        handCount: 1,
        hand: [{ id: "closure-recover", definitionId: "recover", availability: 1 }],
        knownCards: [],
        statuses: [],
        rejuvenationTriggerCount: 0
      }
    ]
  };
  const rejectedRescueState = structuredClone(rescueState);
  let acceptedRescueCalls = 0;
  let rejectedRescueCalls = 0;
  new Simulator(rescueState, {
    decideDyingRescue: () => (acceptedRescueCalls += 1, true)
  }).resolveFatal(rescueState, rescueState.players[0]);
  new Simulator(rejectedRescueState, {
    decideDyingRescue: () => (rejectedRescueCalls += 1, false)
  }).resolveFatal(rejectedRescueState, rejectedRescueState.players[0]);
  assert.equal(rescueState.players[0].alive, true);
  assert.equal(rescueState.players[0].hp, 1);
  assert.equal(rescueState.players[1].handCount, 0);
  assert.equal(rejectedRescueState.players[0].alive, false);
  assert.equal(rejectedRescueState.players[1].handCount, 1);
  assert.equal(acceptedRescueCalls, 1);
  assert.equal(rejectedRescueCalls, 1);
}

test(
  "AI·核心链路：Block/Guardian/Rescue willingness 与 transition 分离",
  responseWillingnessTransitionGate
);

test("AI·架构：正式目录无静态依赖环、旧兼容路径或内部 service locator", async () => {
  const aiRoot = projectFile("js/ai");
  const files = (await listJavaScriptFiles(aiRoot)).map((file) => nodePath.normalize(file));
  const fileSet = new Set(files);
  const rootFiles = (await readdir(aiRoot, { withFileTypes: true }))
    .filter((entry) => entry.isFile() && entry.name.endsWith(".js"))
    .map((entry) => entry.name)
    .sort();
  assert.deepEqual(rootFiles, ["Controller.js"]);
  assert.deepEqual(files.map((file) => (
    nodePath.relative(aiRoot, file).split(nodePath.sep).join("/")
  )).sort(), [
    "Controller.js",
    "Evaluator/CardValue.js",
    "Evaluator/Evaluator.js",
    "Evaluator/StateValue.js",
    "Event/Fact.js",
    "Event/Probability/Branch.js",
    "Event/Probability/Pool.js",
    "Event/Probability/Probability.js",
    "Generator/Action.js",
    "Generator/Generator.js",
    "Searcher/Pattern.js",
    "Searcher/Rng.js",
    "Searcher/Searcher.js",
    "Simulator/Damage.js",
    "Simulator/Resource.js",
    "Simulator/Response.js",
    "Simulator/Simulator.js",
    "Simulator/World.js"
  ]);

  const removedCompatibilityNames = new Set([
    "AiSimulator", "AiEvaluator", "AiStateValue", "AiVisibleState", "AiKnowledge",
    "AiProbabilityBranches", "AiEconomics", "ThreatCalculator", "roleCardValue",
    "discardScoring", "resourceSelectionValue", "transferScoring", "sealScoring",
    "lightningScoring", "AiGlobalBenefit", "AiPlanner", "AiActionGenerator",
    "AiCardSelector", "AiResponsePolicy", "AiValueSimulationQuery",
    "ResponsePolicy", "ResponseBoundary",
    "Planner", "SearchPolicy", "TransitionValue", "FrontierValue",
    "CandidateMaterializer", "SiblingTransitionTerms", "SearchResult"
  ]);
  const componentNames = new Set([
    "ResponseSimulation", "CombatSimulation", "CardEffectSimulation",
    "SkillEffectSimulation", "StatusSimulation"
  ]);
  const graph = new Map();
  const importPattern = /^\s*import\s+(?:[^"'`;]*?\s+from\s+)?["']([^"']+)["']/gm;
  for (const file of files) {
    const source = await readFile(file, "utf8");
    assert.doesNotMatch(
      source,
      /ResponseBoundary|SealPrior|SealValue|GlobalBenefitValue|CandidateMaterializer|\bPlanner\b|GlobalBenefitModel|value\/Evaluator|accepted plan|(?:persistent|持久)[^\n]*(?:momentumBranches|attackUseSlots)|(?:momentumBranches|attackUseSlots)[^\n]*(?:persistent|持久)/,
      `${file} 保留 stale architecture comment`
    );
    const code = source.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, "");
    assert.doesNotMatch(code, /\b(?:this\.)?game\.aiController\b/, file);
    const dependencies = [];
    for (const match of code.matchAll(importPattern)) {
      const specifier = match[1].split("?")[0];
      if (!specifier.startsWith(".")) continue;
      const target = nodePath.normalize(nodePath.resolve(nodePath.dirname(file), specifier));
      const importedName = nodePath.basename(target, ".js");
      assert.equal(removedCompatibilityNames.has(importedName), false, `${file} -> ${specifier}`);
      if (componentNames.has(importedName)) {
        assert.equal(
          nodePath.dirname(file),
          nodePath.dirname(target),
          `Simulation component leaked outside simulation/: ${file} -> ${specifier}`
        );
      }
      if (fileSet.has(target)) dependencies.push(target);
    }
    graph.set(file, dependencies);
  }

  const visiting = new Set();
  const visited = new Set();
  const stack = [];
  const visit = (file) => {
    if (visiting.has(file)) {
      const start = stack.indexOf(file);
      assert.fail(`AI static import cycle: ${[...stack.slice(start), file]
        .map((entry) => nodePath.relative(aiRoot, entry)).join(" -> ")}`);
    }
    if (visited.has(file)) return;
    visiting.add(file);
    stack.push(file);
    for (const dependency of graph.get(file) ?? []) visit(dependency);
    stack.pop();
    visiting.delete(file);
    visited.add(file);
  };
  for (const file of files) visit(file);
});

/*
功能
验证 AI production 模块只公开仍有生产或测试 caller 的 export。

调用方
AI 架构测试。

输入
无。

输出
无返回值；已内部化或已删除 symbol 再次导出时抛断言。

读取状态
Controller、Evaluator、StateValue、Probability、Branch 与 Searcher 模块命名导出。

写入状态
无。

调用函数
动态 import、Object.hasOwn、assert。

边界与不变量
只锁定本轮经全仓调用图证明无 caller 的表面；有真实测试/研究工具 caller 的导出继续保留。
*/
async function unusedAiExportClosure() {
  const [controller, evaluator, stateValue, probability, branch, searcher] = await Promise.all([
    import("../js/ai/Controller.js"),
    import("../js/ai/Evaluator/Evaluator.js"),
    import("../js/ai/Evaluator/StateValue.js"),
    import("../js/ai/Event/Probability/Probability.js"),
    import("../js/ai/Event/Probability/Branch.js"),
    import("../js/ai/Searcher/Searcher.js")
  ]);
  const removedExports = new Map([
    [controller, ["createRuntimeComposition"]],
    [evaluator, [
      "assessGlobalBenefit", "getBaseCardAiValue", "getEquipmentKeepValueDeduction",
      "getRoleCardAiValue", "roleCardDelta", "HP_VALUE", "incomingExposure",
      "statePointsToUtility", "turnOpportunityValue"
    ]],
    [stateValue, [
      "DANGER_VALUE", "energyDeviceFutureUtility", "radarMitigationUtility", "shieldStateValue"
    ]],
    [probability, [
      "binaryConditionPartition", "getAvailabilityBranches", "mergeProbabilityBranches",
      "mergeProbabilityBranchesCooperatively", "queryCardCategoryProbability"
    ]],
    [branch, ["binaryConditionPartition", "mergeProbabilityBranches", "mergeProbabilityBranchesCooperatively"]],
    [searcher, ["SEARCH_STOP_REASON"]]
  ]);
  for (const [module, names] of removedExports) {
    for (const name of names) assert.equal(Object.hasOwn(module, name), false, name);
  }
}

test("AI·架构：unused production exports 已删除或内部化", unusedAiExportClosure);

/*
功能
验证 Probability facade、Branch 与 Pool 的物理边界、正交依赖和旧 Model closure。

调用方
AI 架构测试。

输入
无。

输出
无返回值；结构回流或直连时抛断言。

读取状态
Probability 目录与全部 production JavaScript import。

写入状态
无。

调用函数
readFile、readdir、listJavaScriptFiles、access。

边界与不变量
只有 facade 可 import Branch/Pool；底层彼此无 import，旧 Radar/Lightning/Seal Model 必须不存在。
*/
async function probabilityArchitectureClosure() {
  const directory = projectFile("js/ai/Event/Probability");
  const entries = (await readdir(directory)).sort();
  assert.deepEqual(entries, ["Branch.js", "Pool.js", "Probability.js"]);
  const branchPath = projectFile("js/ai/Event/Probability/Branch.js");
  const poolPath = projectFile("js/ai/Event/Probability/Pool.js");
  const facadePath = projectFile("js/ai/Event/Probability/Probability.js");
  const branch = await readFile(branchPath, "utf8");
  const pool = await readFile(poolPath, "utf8");
  const facade = await readFile(facadePath, "utf8");
  assert.doesNotMatch(branch, /^import\s/m);
  assert.doesNotMatch(pool, /^import\s/m);
  assert.match(facade, /from "\.\/Branch\.js"/);
  assert.match(facade, /from "\.\/Pool\.js"/);
  assert.doesNotMatch(facade, /export\s+\*/);

  const internalPaths = new Set([branchPath, poolPath, facadePath].map(nodePath.normalize));
  for (const file of await listJavaScriptFiles(projectFile("js"))) {
    if (internalPaths.has(nodePath.normalize(file))) continue;
    const source = await readFile(file, "utf8");
    assert.doesNotMatch(
      source,
      /Probability\/(?:Branch|Pool)\.js/,
      `${file} 不得绕过 Probability facade`
    );
  }
  const branchCode = branch.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, "");
  const poolCode = pool.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, "");
  const facadeCode = facade.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, "");
  assert.doesNotMatch(
    branchCode,
    /\b(?:recover|block|counter|assault|Radar|Lightning|Seal|equipment|huntMark)\b/
  );
  assert.doesNotMatch(poolCode, /\b(?:Radar|Lightning|Seal|Simulator|Evaluator|Generator)\b/);
  assert.match(poolCode, /function consumeSequencePool\s*\(/);
  assert.match(poolCode, /export function finitePoolSequence\s*\(/);
  assert.match(poolCode, /slotCount\s*>\s*maxSlotCount/);
  assert.doesNotMatch(
    facadeCode,
    /\[outcome\]\s*:\s*[^,\n]+-\s*1|world\.total\s*-\s*1/
  );
  for (const file of ["RadarModel.js", "LightningModel.js", "SealModel.js"]) {
    await assert.rejects(access(projectFile(`js/ai/domain/${file}`)));
  }
}

test("AI·Probability 架构：Facade/Branch/Pool 正交且旧 Model 引用闭合", probabilityArchitectureClosure);

