/*
功能
验证互利 canonical Action 从 Generator 到 Worker、main acceptance 与真实执行边界的完整 runtime 链。

调用方
FR-ARCH-14 runtime regression。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
SearchRequest/Action/WorkerSearchRuntime/AIController/Game playCard/PublicCardPool。

写入状态
测试 Game 状态。

调用函数
makePlayer、makeGame、instance、createInitialWorld、getActionCandidates、createSearchRequest、runSearchRequest、createWorkerSearchOutcome、acceptWorkerSearchOutcome、Game.playCard。

边界与不变量
Search 选择是否 end 不影响执行边界验证；Worker 与 main thread 不投影或重建 Action，真实执行只按 ID 解析当前实体。
*/
async function frArch14MutualBenefitRuntimeTrace() {
  const { runSearchRequest } = await import("../js/adapters/ai/worker/WorkerSearchRuntime.js");
  const { createSearchRequest } = await import("../js/ai/Controller.js");
  const { createWorkerSearchOutcome, workerOutcomeViolations } = await import("../js/ai/Controller.js");
  const actor = makePlayer("mb-runtime-actor", 0, "dawn", "ai", 0);
  const enemy = makePlayer("mb-runtime-enemy", 1, "dusk", "ai", 1);
  const benefit = instance("mutualBenefit");
  actor.hand.push(benefit);
  const { game } = makeGame([actor, enemy]);
  game.state.deck.cards = [instance("block"), instance("charge")];
  game.aiSearchNodeBudgetOverride = 8;
  const roots = game.aiController.getActionCandidates(actor);
  const root = roots.find((action) => action.cardId === "mutualBenefit");
  assert.ok(root, "root candidate 必须包含 mutualBenefit");
  const visible = createInitialWorld(actor.id, game.state);
  assert.deepEqual(structuredClone(root), root);
  const request = createSearchRequest({
    requestId: "mb-runtime-request",
    gameId: game.state.gameId,
    stateVersion: game.state.stateVersion,
    actorId: actor.id,
    phase: game.state.phase,
    currentRound: game.state.currentRound,
    world: visible,
    searchConfig: game.aiController.buildSearchConfig(),
    rng: game.aiController.searchRng.snapshot(),
    rootActions: roots
  });
  assert.ok(request.rootActions.some((entry) => entry.cardId === "mutualBenefit"));
  const outcome = await runSearchRequest(request, { yieldControl: async () => true });
  assert.deepEqual(workerOutcomeViolations(outcome, request), []);
  assert.deepEqual(structuredClone(outcome), outcome);
  assert.ok(outcome.action === null || request.rootActions.some(
    (descriptor) => JSON.stringify(descriptor) === JSON.stringify(outcome.action)
  ));
  const executionOutcome = createWorkerSearchOutcome({
    request,
    action: root,
    stats: outcome.stats,
    searchStopReason: "COMPLETE",
    rngAfter: outcome.rngAfter
  });
  const accepted = game.aiController.acceptWorkerSearchOutcome(request, executionOutcome);
  assert.equal(accepted.result.status, SEARCH_RESULT_STATUS.ACCEPTED);
  assert.equal(accepted.action.type, "card");
  assert.equal(accepted.action.cardInstanceId, benefit.id);
  assert.deepEqual(accepted.action.targetIds, [actor.id, enemy.id]);
  const executionCard = actor.hand.find((card) => card.id === accepted.action.cardInstanceId);
  const executionTargets = accepted.action.targetIds.map(
    (targetId) => game.state.players.find((player) => player.id === targetId)
  );
  assert.equal(await game.playCard(
    actor,
    executionCard,
    executionTargets,
    accepted.action.selection
  ), true);
  assert.equal(actor.hand.length, 1);
  assert.equal(enemy.hand.length, 1);
  assert.equal(game.state.publicCardPool.length, 0);
  assert.ok(game.state.deck.discardPile.includes(benefit));
  game.dispose();
}

test("AI·Worker 互利链路：root → worker → acceptance → execution → public pool 全链", frArch14MutualBenefitRuntimeTrace);

/*
功能
覆盖 AI 强制弃牌不变量：HP 1/2/3、多余1/2/多张、三档展示速度，以及 AI choice cancelled 或 selectedIds 不足时仍收束到 hand.length <= hp。

调用方
FR-ARCH-14 runtime regression。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
TurnWorkflow.handleDiscardPhase 与 AI_SEARCH_PROFILE。

写入状态
测试 Game 手牌/弃牌堆。

调用函数
new Game、makePlayer、instance、createChoiceResult、handleDiscardPhase。

边界与不变量
兜底只保证 AI 弃牌收束，不改变正常 AI 选牌策略；真人取消仍保留既有交互语义。
*/
async function frArch14DiscardInvariantMatrix() {
  const makeFixture = (hp, handCount, speed, choiceKind) => {
    const ui = makeUi();
    const game = createGameApplication(ui, () => 0.25, {
      choicePort: {
        async request(choiceRequest) {
          if (choiceRequest?.kind !== "discard") return createChoiceResult("declined");
          if (choiceKind === "cancelled") return createChoiceResult("cancelled");
          const selectedIds = choiceRequest.options.slice(0, 1).map((option) => option.optionId);
          return createChoiceResult("selected", { selectedIds });
        }
      }
    });
    const player = makePlayer(`discard-${hp}-${handCount}-${speed}-${choiceKind}`, 0, "dawn", "ai", 0);
    const enemy = makePlayer(`discard-enemy-${hp}-${handCount}-${speed}-${choiceKind}`, 1, "dusk", "ai", 1);
    player.hp = hp;
    for (let index = 0; index < handCount; index += 1) {
      player.hand.push(instance(["assault", "scout", "recover", "block", "charge", "counter"][index % 6]));
    }
    game.state.players = [player, enemy];
    game.state.currentPlayerIndex = 0;
    game.state.phase = "discard";
    game.aiSpeed = speed;
    game.cleanupManager.delay = async () => true;
    return { game, player };
  };
  for (const hp of [1, 2, 3]) {
    for (const extra of [1, 2, 5]) {
      for (const speed of [1, 2, 3]) {
        for (const choiceKind of ["cancelled", "partial"]) {
          const { game, player } = makeFixture(hp, hp + extra, speed, choiceKind);
          const profile = game.aiController.buildSearchConfig();
          assert.equal(profile.searchMode, AI_SEARCH_PROFILE.mode);
          assert.equal(profile.timeBudgetMs, AI_RUNTIME_POLICY.searchTimeBudgetMs);
          assert.equal(Object.hasOwn(profile, "searchDeadlineMs"), false);
          assert.equal(profile.hardWatchdogMs, 10000);
          await game.turnWorkflow.handleDiscardPhase(player, game.state.gameId);
          assert.ok(player.hand.length <= hp, `hp=${hp} hand=${hp + extra} speed=${speed} ${choiceKind}`);
          game.dispose();
        }
      }
    }
  }
}

test("AI·Worker 弃牌：AI HP1/2/3 三档速度与取消/不足选择后不超手牌上限", frArch14DiscardInvariantMatrix);

/*
功能
用 fake Dedicated Worker/timer 验证 SearchWorkerClient 的接线、postMessage 诊断、terminal settle、取消、hard watchdog 重建与 production transport 选择。

调用方
FR-ARCH-14 browser transport regression。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
SearchWorkerClient 与 createSearchExecutor。

写入状态
fake Worker 消息队列、fake watchdog timer 与测试 executor。

调用函数
createSearchWorkerClient、createSearchExecutor。

边界与不变量
不执行真实 search；heartbeat 续期只替换静默 watchdog，terminal exactly-once；真正静默/crash/cancel 才终止并重建。
*/
async function frArch14WorkerClientTransport() {
  const { createSearchWorkerClient } = await import("../js/adapters/ai/worker/SearchWorkerClient.js");
  const { createSearchExecutor } = await import("../js/adapters/ai/worker/createSearchExecutor.js");
  const instances = [];
  class FakeWorker {
    constructor(url, options) {
      this.url = url;
      this.options = options;
      this.listeners = new Map();
      this.posted = [];
      this.terminated = false;
      this.throwOnPost = false;
      instances.push(this);
    }
    addEventListener(type, listener) {
      if (!this.listeners.has(type)) this.listeners.set(type, []);
      this.listeners.get(type).push(listener);
    }
    postMessage(message) {
      if (this.throwOnPost) throw new Error("structuredClone failed");
      this.posted.push(message);
    }
    terminate() { this.terminated = true; }
    emit(type, data) {
      const event = type === "message" ? { data } : data ?? {};
      for (const listener of this.listeners.get(type) ?? []) listener(event);
    }
  }
  const previousWorker = Object.getOwnPropertyDescriptor(globalThis, "Worker");
  const previousWindow = Object.getOwnPropertyDescriptor(globalThis, "window");
  const previousDocument = Object.getOwnPropertyDescriptor(globalThis, "document");
  delete globalThis.Worker;
  delete globalThis.window;
  delete globalThis.document;
  const headlessExecutor = createSearchExecutor({});
  assert.equal(headlessExecutor.transport, "headless-local", "Node/headless 无 Worker 时必须保留本地 transport");
  headlessExecutor.dispose();
  Object.defineProperty(globalThis, "Worker", { configurable: true, writable: true, value: FakeWorker });
  try {
    const makeOutcome = (requestId) => ({
      requestId,
      gameId: "game-1",
      stateVersion: 0,
      actorId: "actor-1",
      action: { type: "end", cardId: null, cardInstanceId: null, targetId: null, targetIds: [], selection: null },
      stats: null,
      searchStopReason: "COMPLETE",
      rngAfter: { seed: 1, state: 1, algorithm: "lcg", draws: 0 },
      cancelled: false,
      workerError: null
    });
    const makeRequest = (requestId, searchConfig = {}) => ({
      requestId,
      gameId: "game-1",
      stateVersion: 0,
      actorId: "actor-1",
      searchConfig: { hardWatchdogMs: 5000, ...searchConfig }
    });
    const client = createSearchWorkerClient("searchWorker.js");
    assert.equal(instances.length, 1, "首个 production Worker 必须立即接线");
    const firstWorker = instances[0];
    assert.deepEqual(client.getLifecycleDiagnostics(), {
      workerCreated: 1,
      workerTerminated: 0,
      searchStarted: 0,
      searchCompleted: 0,
      searchTimedOut: 0,
      searchCancelled: 0,
      searchWatchdog: 0,
      searchFaulted: 0,
      searchHeartbeats: 0,
      orphanSearchCount: 0,
      activeWorkerCount: 1,
      activeSearchCount: 0,
      requestId: null
    });
    assert.equal(firstWorker.listeners.get("message")?.length, 1);
    const firstRequest = makeRequest("first");
    const firstPromise = client.search(firstRequest);
    assert.equal(client.getLifecycleDiagnostics().activeSearchCount, 1);
    assert.equal(firstWorker.posted[0].type, "SEARCH");
    assert.equal(client.getLastTransportDiagnostics().requestId, "first");
    assert.ok(client.getLastTransportDiagnostics().postMessageMs >= 0);
    firstWorker.emit("message", { type: "RESULT", requestId: "first", outcome: makeOutcome("first") });
    assert.deepEqual(await firstPromise, makeOutcome("first"));
    assert.equal(client.getLifecycleDiagnostics().searchCompleted, 1);
    assert.equal(client.getLifecycleDiagnostics().activeSearchCount, 0);
    const timeOutcome = { ...makeOutcome("time"), searchStopReason: "TIME" };
    const timePromise = client.search(makeRequest("time"));
    firstWorker.emit("message", { type: "RESULT", requestId: "time", outcome: timeOutcome });
    assert.deepEqual(await timePromise, timeOutcome);
    assert.equal(client.getLifecycleDiagnostics().searchTimedOut, 1);
    assert.equal(client.getLifecycleDiagnostics().activeSearchCount, 0);
    assert.equal(client.getLifecycleDiagnostics().activeWorkerCount, 1,
      "TIME 后保留的 Worker 必须已空闲且可复用");
    firstWorker.emit("message", { type: "RESULT", requestId: "first", outcome: makeOutcome("first") });
    client.dispose();
    assert.equal(firstWorker.terminated, true);

    const recoveryClient = createSearchWorkerClient("searchWorker.js");
    const recoveryWorker = instances[1];
    recoveryWorker.throwOnPost = true;
    await assert.rejects(recoveryClient.search(makeRequest("clone-fail")), /structuredClone failed/);
    assert.equal(recoveryClient.getLastTransportDiagnostics().requestId, "clone-fail");
    recoveryWorker.throwOnPost = false;
    const secondPromise = recoveryClient.search(makeRequest("second"));
    recoveryWorker.emit("message", { type: "ERROR", requestId: "stale", workerError: "stale error" });
    recoveryWorker.emit("message", { type: "RESULT", requestId: "second", outcome: makeOutcome("second") });
    assert.deepEqual(await secondPromise, makeOutcome("second"));
    const cancelPromise = recoveryClient.search(makeRequest("cancel-me"));
    recoveryClient.cancel("not-current");
    assert.equal(recoveryWorker.terminated, false, "非当前 requestId 不得终止 Worker");
    recoveryClient.cancel("cancel-me");
    await assert.rejects(cancelPromise, (error) => (
      error?.name === "AbortError" && /cancelled/.test(error.message)
    ));
    assert.ok(recoveryWorker.posted.some((message) => message.type === "CANCEL" && message.requestId === "cancel-me"));
    assert.equal(recoveryWorker.terminated, true);
    const rebuiltAfterCancel = instances.at(-1);
    assert.notEqual(rebuiltAfterCancel, recoveryWorker);
    assert.equal(recoveryClient.getLifecycleDiagnostics().workerCreated, 2);
    assert.equal(recoveryClient.getLifecycleDiagnostics().workerTerminated, 1);
    assert.equal(recoveryClient.getLifecycleDiagnostics().searchCancelled, 1);
    assert.equal(recoveryClient.getLifecycleDiagnostics().activeWorkerCount, 1);
    assert.equal(recoveryClient.getLifecycleDiagnostics().activeSearchCount, 0);
    assert.equal(recoveryClient.getLifecycleDiagnostics().orphanSearchCount, 0);
    const afterCancelPromise = recoveryClient.search(makeRequest("after-cancel"));
    recoveryWorker.emit("message", {
      type: "RESULT",
      requestId: "after-cancel",
      outcome: makeOutcome("after-cancel")
    });
    assert.equal(recoveryClient.getLifecycleDiagnostics().activeSearchCount, 1,
      "旧 Worker 迟到消息不得结算新 request");
    rebuiltAfterCancel.emit("message", {
      type: "RESULT",
      requestId: "after-cancel",
      outcome: makeOutcome("after-cancel")
    });
    assert.deepEqual(await afterCancelPromise, makeOutcome("after-cancel"));
    const crashPromise = recoveryClient.search(makeRequest("worker-crash"));
    rebuiltAfterCancel.emit("error", { message: "synthetic Worker crash" });
    await assert.rejects(crashPromise, /synthetic Worker crash/);
    const rebuiltAfterCrash = instances.at(-1);
    assert.notEqual(rebuiltAfterCrash, rebuiltAfterCancel,
      "真正 Worker crash 后必须终止旧实例并重建");
    assert.equal(recoveryClient.getLifecycleDiagnostics().searchFaulted, 2,
      "postMessage fault 与 Worker crash 都必须保留 transport fault 分类");
    assert.equal(recoveryClient.getLifecycleDiagnostics().activeSearchCount, 0);
    const afterCrashPromise = recoveryClient.search(makeRequest("after-crash"));
    rebuiltAfterCrash.emit("message", {
      type: "RESULT",
      requestId: "after-crash",
      outcome: makeOutcome("after-crash")
    });
    assert.deepEqual(await afterCrashPromise, makeOutcome("after-crash"));
    recoveryClient.dispose();

    const scheduledTimers = [];
    const hardWatchdogClient = createSearchWorkerClient("searchWorker.js", {
      setTimeout(callback, milliseconds) {
        const timer = { callback, milliseconds, cancelled: false };
        scheduledTimers.push(timer);
        return timer;
      },
      clearTimeout(timer) {
        if (timer) timer.cancelled = true;
      }
    });
    const hardWatchdogWorker = instances.at(-1);
    const longSearchPromise = hardWatchdogClient.search(makeRequest(
      "long-search",
      { hardWatchdogMs: 10000 }
    ));
    const initialWatchdog = scheduledTimers.at(-1);
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().activeSearchCount, 1,
      "pending request 在正常长搜索 terminal 前必须保留");
    hardWatchdogWorker.emit("message", { type: "HEARTBEAT", requestId: "long-search" });
    const renewedWatchdog = scheduledTimers.at(-1);
    assert.notEqual(renewedWatchdog, initialWatchdog);
    assert.equal(initialWatchdog.cancelled, true);
    initialWatchdog.callback();
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().activeSearchCount, 1,
      "已被 heartbeat 取代的 watchdog 不得提前清理 pending");
    hardWatchdogWorker.emit("message", {
      type: "RESULT",
      requestId: "long-search",
      outcome: makeOutcome("long-search")
    });
    renewedWatchdog.callback();
    hardWatchdogWorker.emit("message", { type: "HEARTBEAT", requestId: "long-search" });
    hardWatchdogWorker.emit("message", {
      type: "RESULT",
      requestId: "long-search",
      outcome: makeOutcome("long-search")
    });
    assert.deepEqual(await longSearchPromise, makeOutcome("long-search"));
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().searchCompleted, 1);
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().searchHeartbeats, 1);
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().searchWatchdog, 0);
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().activeSearchCount, 0,
      "terminal cleanup 后旧 heartbeat/watchdog 不得再次 failure");

    const racePromise = hardWatchdogClient.search(makeRequest(
      "heartbeat-terminal-race",
      { hardWatchdogMs: 10000 }
    ));
    hardWatchdogWorker.emit("message", {
      type: "HEARTBEAT",
      requestId: "heartbeat-terminal-race"
    });
    const raceWatchdog = scheduledTimers.at(-1);
    hardWatchdogWorker.emit("message", {
      type: "RESULT",
      requestId: "heartbeat-terminal-race",
      outcome: makeOutcome("heartbeat-terminal-race")
    });
    raceWatchdog.callback();
    assert.deepEqual(await racePromise, makeOutcome("heartbeat-terminal-race"));
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().searchCompleted, 2,
      "heartbeat 与 terminal 接近时只能完成一次");
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().searchWatchdog, 0);

    const hardWatchdogPromise = hardWatchdogClient.search(makeRequest(
      "hard-watchdog",
      { hardWatchdogMs: 10000 }
    ));
    const hardWatchdogRejection = assert.rejects(hardWatchdogPromise, /hard watchdog/);
    const crashWatchdog = scheduledTimers.at(-1);
    assert.equal(crashWatchdog.milliseconds, 10000);
    crashWatchdog.callback();
    await hardWatchdogRejection;
    assert.ok(hardWatchdogWorker.posted.some(
      (message) => message.type === "CANCEL" && message.requestId === "hard-watchdog"
    ));
    assert.equal(hardWatchdogWorker.terminated, true);
    assert.notEqual(instances.at(-1), hardWatchdogWorker, "hard watchdog 后必须重建下一 Worker");
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().searchWatchdog, 1);
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().activeSearchCount, 0);
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().activeWorkerCount, 1);
    assert.equal(hardWatchdogClient.getLifecycleDiagnostics().orphanSearchCount, 0);
    hardWatchdogClient.dispose();

    const executor = createSearchExecutor({});
    assert.equal(executor.transport, "dedicated-worker", "browser 存在 Worker 时 production 必须使用 Dedicated Worker");
    executor.dispose();
    assert.equal(createSearchExecutor({ forceLocal: true }).transport, "headless-local");

    delete globalThis.Worker;
    Object.defineProperty(globalThis, "window", { configurable: true, value: {} });
    Object.defineProperty(globalThis, "document", { configurable: true, value: {} });
    assert.throws(
      () => createSearchExecutor({}),
      /不支持 Dedicated Worker.*不能回退到主线程/
    );
  } finally {
    for (const instance of instances) instance.terminate();
    if (previousWorker) Object.defineProperty(globalThis, "Worker", previousWorker);
    else delete globalThis.Worker;
    if (previousWindow) Object.defineProperty(globalThis, "window", previousWindow);
    else delete globalThis.window;
    if (previousDocument) Object.defineProperty(globalThis, "document", previousDocument);
    else delete globalThis.document;
  }
}

test("AI·Worker 传输：Dedicated Worker 初始接线/结果/清理/恢复与 production 选择", frArch14WorkerClientTransport);

/*
功能
对同一固定 World 比较 Controller public search engine 与 Worker runtime 的完整确定性 trace。

调用方
FR-ARCH-14 worker search parity audit。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
Searcher/runSearchRequest/SearchRng/Action。

写入状态
测试 Game 与两个独立 SearchRng continuation。

调用函数
makeGame、instance、getActionCandidates、createInitialWorld、createSearchRequest、SearchRng.restore、createSearchEngine、Searcher.search、runSearchRequest。

边界与不变量
固定 node budget 保证双方同 stopReason；Worker 只运输 root Action，多步序列只保留在诊断 stats。
*/
async function frArch14WorkerSearchParityTrace() {
  const { runSearchRequest } = await import("../js/adapters/ai/worker/WorkerSearchRuntime.js");
  const { createSearchEngine } = await import("../js/ai/Controller.js");
  const { createSearchRequest } = await import("../js/ai/Controller.js");
  const actor = makePlayer("parity-actor", 0, "dawn", "ai", 0);
  const ally = makePlayer("parity-ally", 2, "dawn", "ai", 2);
  const enemy = makePlayer("parity-enemy", 1, "dusk", "ai", 1);
  actor.hand.push(instance("assault"), instance("assault"), instance("scout"), instance("recover"));
  const { game } = makeGame([actor, enemy, ally]);
  game.aiRandomnessRange = 0;
  game.aiSearchNodeBudgetOverride = 120;
  game.aiController.searchRng = new SearchRng(777001);
  const player = game.state.players[0];
  const roots = game.aiController.getActionCandidates(player);
  const visible = createInitialWorld(player.id, game.state);
  const before = game.aiController.searchRng.snapshot();
  const request = createSearchRequest({
    requestId: "parity-request",
    gameId: game.state.gameId,
    stateVersion: game.state.stateVersion,
    actorId: player.id,
    phase: game.state.phase,
    currentRound: game.state.currentRound,
    world: visible,
    searchConfig: game.aiController.buildSearchConfig(),
    rng: before,
    rootActions: roots
  });
  const directRng = SearchRng.restore(before);
  const directEngine = createSearchEngine(request, directRng, {
    yieldControl: async () => true
  });
  const mainAction = await directEngine.searcher.search(
    player,
    visible,
    roots,
    { gameId: game.state.gameId, rootCandidateCount: roots.length }
  );
  const mainStats = { ...directEngine.searcher.lastSearchStats };
  const mainSequence = structuredClone(directEngine.searcher.lastSequence);
  const mainAfter = directRng.snapshot();
  const outcome = await runSearchRequest(request, { yieldControl: async () => true });
  assert.deepEqual(outcome.action, mainAction);
  assert.equal(Object.hasOwn(outcome, "plannedActions"), false);
  assert.deepEqual(outcome.stats.bestSequence, mainSequence);
  assert.equal(outcome.searchStopReason, mainStats.stopReason);
  assert.equal(outcome.stats.expanded, mainStats.expanded);
  assert.equal(outcome.stats.depth, mainStats.depth);
  assert.equal(outcome.stats.hiddenSamples, mainStats.hiddenSamples);
  assert.equal(outcome.stats.simulationCalls, mainStats.simulationCalls);
  assert.equal(outcome.stats.counterfactualCalls, mainStats.counterfactualCalls);
  assert.equal(outcome.stats.stateUtilityCalls, mainStats.stateUtilityCalls);
  assert.equal(outcome.stats.bestValueScore, mainStats.bestValueScore);
  assert.deepEqual(outcome.rngAfter, mainAfter);
  game.dispose();
}

test("AI·Worker 搜索一致性：只运输 root Action 且多步序列仅保留在诊断", frArch14WorkerSearchParityTrace);

/*
功能
验证连续 accepted Worker search 的 RNG continuation，以及 WORKER_FAILURE 不提交 RNG。

调用方
FR-ARCH-14 RNG continuity runtime audit。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
AIController selectAction/acceptWorkerSearchOutcome、SearchPrior fallback 与 SearchRng。

写入状态
测试 Game 与 SearchRng。

调用函数
makeGame、instance、selectAction、acceptWorkerSearchOutcome、createWorkerSearchOutcome。

边界与不变量
正常结果只提交一次 RNG；Worker fault 返回 null Action 与 WORKER_FAILURE，不提交失败 outcome 的 RNG。
*/
async function frArch14RngContinuityAcceptedSearches() {
  const { createWorkerSearchOutcome } = await import("../js/ai/Controller.js");
  const actor = makePlayer("rng-continuity-actor", 0, "dawn", "ai", 0);
  const enemy = makePlayer("rng-continuity-enemy", 1, "dusk", "ai", 1);
  actor.hand.push(instance("assault"));
  const { game } = makeGame([actor, enemy]);
  game.aiSearchNodeBudgetOverride = 12;
  game.aiController.searchRng = new SearchRng(9001);
  const player = game.state.players[0];
  const firstAction = await game.aiController.selectAction(player, { gameId: game.state.gameId });
  assert.ok(["card", "end"].includes(firstAction.type));
  const firstResult = game.aiController.lastSearchResult;
  const firstRequest = game.aiController.lastSearchRequest;
  const firstOutcome = game.aiController.lastWorkerOutcome;
  assert.equal(firstResult.status, SEARCH_RESULT_STATUS.ACCEPTED);
  assert.deepEqual(game.aiController.searchRng.snapshot(), firstResult.rngAfter);
  const secondAction = await game.aiController.selectAction(player, { gameId: game.state.gameId });
  assert.ok(["card", "end"].includes(secondAction.type));
  const secondRequest = game.aiController.lastSearchRequest;
  assert.deepEqual(secondRequest.rng, firstResult.rngAfter, "Search2.rngBefore 必须等于 Search1.accepted.rngAfter");
  assert.equal(game.aiController.lastSearchResult.status, SEARCH_RESULT_STATUS.ACCEPTED);
  const beforeDuplicate = game.aiController.searchRng.snapshot();
  const duplicate = game.aiController.acceptWorkerSearchOutcome(firstRequest, firstOutcome);
  assert.equal(duplicate.result.rngAfter, null, "duplicate RESULT 不得二次 commit");
  assert.deepEqual(game.aiController.searchRng.snapshot(), beforeDuplicate);
  const beforeRejected = game.aiController.searchRng.snapshot();
  game.aiController.searchExecutor = {
    search: async (request) => createWorkerSearchOutcome({
      request,
      action: null,
      stats: null,
      searchStopReason: null,
      rngAfter: request.rng,
      cancelled: false,
      workerError: "AI search hard watchdog"
    })
  };
  const rejectedAction = await game.aiController.selectAction(player, { gameId: game.state.gameId });
  assert.equal(rejectedAction, null);
  assert.equal(game.aiController.lastSearchResult.status, SEARCH_RESULT_STATUS.WORKER_FAILURE);
  assert.deepEqual(game.aiController.searchRng.snapshot(), beforeRejected, "rejected outcome 不得 commit RNG");
  assert.equal(game.aiController.searchDiagnostics.WORKER_ERROR, 1);
  assert.equal(game.aiController.searchDiagnostics.WATCHDOG, 1);
  assert.equal(game.aiController.lastDecisionDiagnostics.watchdogFired, true);
  assert.equal(
    game.aiController.lastDecisionDiagnostics.workerRejectionReason,
    "AI search hard watchdog"
  );
  assert.equal(
    game.aiController.lastDecisionDiagnostics.controllerFallbackReason,
    "AI search hard watchdog"
  );
  game.dispose();
}

