test("AI·借势：风险：动态格挡剩余0时防御装备不再抬高非零风险", () => {
  const makeState = (defense) => (
    {
      remainingCardCounts: { block: 0, assault: 10 },
      players: [
        {
          id: "actor",
          seatIndex: 0,
          battleTeam: "dawn",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 1,
          hand: [{ id: "l", definitionId: "leverage" }],
          counterProbability: 0,
          expectedEquipmentGain: 0
        },
        {
          id: "first",
          seatIndex: 1,
          battleTeam: "dusk",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 2,
          hand: [{ id: "a1", definitionId: "assault" }],
          attackUsed: 0,
          attackLimit: 1,
          attackRange: 1,
          equipmentDefinitionId: "energyDevice",
          equipmentRetentionProbability: 1,
          assaultResponseProbability: 1,
          expectedAssaultCount: 1,
          blockProbability: 0,
          counterProbability: 0
        },
        {
          id: "second",
          seatIndex: 2,
          battleTeam: "dawn",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 0,
          blockProbability: 0,
          twoBlockProbability: 0,
          counterProbability: 0,
          equipmentDefinitionId: defense ? "defenseDevice" : null,
          equipmentRetentionProbability: defense ? 1 : 0
        }
      ]
    }
  );
  const action = {
    type: "card",
    card: { ...CARD_DEFINITIONS.leverage, id: "l" },
    targets: [{ id: "first" }, { id: "second" }],
    selection: { firstTargetId: "first", secondTargetId: "second" }
  };
  const without = new Simulator(makeState(false)).apply(makeState(false), action, "actor");
  const withDefense = new Simulator(makeState(true)).apply(makeState(true), action, "actor");
  assertClose(withDefense.players[0].handCount, without.players[0].handCount);
  assertClose(withDefense.players[1].attackUsed, without.players[1].attackUsed);
  assertClose(withDefense.players[2].hp, without.players[2].hp);
});

