// ---- AI 装备行为·雷达 ----

const radarFixtureTarget = (overrides = {}) => (
  {
    id: "target",
    battleTeam: "dusk",
    alive: true,
    hp: 4,
    maxHp: 4,
    shield: 0,
    handCount: 0,
    characterId: "oath-warden",
    blockProbability: 0,
    twoBlockProbability: 0,
    equipmentDefinitionId: "defenseDevice",
    equipmentRetentionProbability: 1,
    expectedRecoverCount: 0,
    ...overrides
  }
);

const radarAttacker = (overrides = {}) => (
  {
    id: "attacker",
    battleTeam: "dawn",
    alive: true,
    hp: 4,
    maxHp: 4,
    shield: 0,
    handCount: 0,
    characterId: "blade-walker",
    expectedRecoverCount: 0,
    ...overrides
  }
);

const radarBattleAttacker = () => radarAttacker(
  { equipmentDefinitionId: "battleDevice", equipmentRetentionProbability: 1 }
);

const radarApply = (target, attacker = radarAttacker(), options = {}, existingState = null) => {
  const state = existingState ?? {
    remainingCardCounts: options.remainingCardCounts ?? null, players: [attacker, target]
  };
  if (
    options.remainingCardCounts !== undefined
  ) state.remainingCardCounts = options.remainingCardCounts;
  const simulator = new Simulator({ players: [] });
  const { remainingCardCounts, ...damageOptions }
    = options;
  simulator.applyDamage(
    state, attacker, target, 1, { canBlock: true, deviceAttack: true, ...damageOptions }
  );
  return { state, simulator, target, attacker };
};

