test("AI·雷达：canonical Probability 单次判定保持质量、空池、override 与输入只读", async () => {
  const counts = { assault: 3, block: 2, counter: 4, defenseDevice: 1 };
  const snapshot = structuredClone(counts);
  const outcome = buildRadarJudgmentProbabilities(counts);
  assertClose(
    outcome.tactic + outcome.equipment
    + Object.values(outcome.basic).reduce((sum, probability) => sum + probability, 0),
    1
  );
  assert.deepEqual(buildRadarJudgmentProbabilities({}), {
    tactic: 0,
    equipment: 0,
    basic: { assault: 0, recover: 0, block: 0, charge: 0, shield: 0 },
    hasJudgmentPool: false
  });
  assert.deepEqual(
    buildRadarJudgmentProbabilities(
      { block: 1, charge: 3, defenseDevice: 2 },
      { block: .2, otherBasic: .3, equipment: .1 }
    ),
    {
      tactic: .4,
      equipment: .1,
      basic: { assault: 0, recover: 0, block: .2, charge: .3, shield: 0 },
      hasJudgmentPool: true
    }
  );
  outcome.basic.assault = -1;
  assert.deepEqual(counts, snapshot);
  assert.equal(JSON.stringify(outcome).includes("game"), false);
  const source = await readFile(
    projectFile("js/ai/Event/Probability/Probability.js"),
    "utf8"
  );
  assert.doesNotMatch(source, /:\s*0\.25\b/);
  assert.match(source, /1\s*\/\s*RADAR_OTHER_BASIC_DEFINITION_IDS\.length/);
});

test("AI·雷达：canonical Probability 多次判定逐槽无放回且不保留 genealogy", () => {
  const counts = { block: 1, charge: 1 };
  const maxRadarSlots = getRequiredBlockCount("battleDevice", true);
  const snapshot = structuredClone(counts);
  const sequence = buildRadarJudgmentSequenceProbabilities(counts, 2, maxRadarSlots);
  assert.deepEqual(sequence, [
    { probability: .5, outcomes: ["basic:block", "basic:charge"] },
    { probability: .5, outcomes: ["basic:charge", "basic:block"] }
  ]);
  assertClose(
    sequence.reduce((sum, branch) => sum + branch.probability, 0),
    1
  );
  assert.deepEqual(
    buildRadarJudgmentSequenceProbabilities({}, 2, maxRadarSlots),
    [{ probability: 1, outcomes: ["noJudgment", "noJudgment"] }]
  );
  assert.deepEqual(
    buildRadarJudgmentSequenceProbabilities(
      counts,
      2,
      maxRadarSlots,
      [
        { block: 1, otherBasic: 0, equipment: 0 },
        { block: 0, otherBasic: 1, equipment: 0 }
      ]
    ),
    [{ probability: 1, outcomes: ["basic:block", "basic:charge"] }]
  );
  const forceBlock = { block: 1, otherBasic: 0, equipment: 0 };
  assert.deepEqual(
    buildRadarJudgmentSequenceProbabilities(
      { block: 1, counter: 1 },
      2,
      maxRadarSlots,
      [forceBlock, null]
    ),
    [{ probability: 1, outcomes: ["basic:block", "tactic"] }]
  );
  assert.deepEqual(
    buildRadarJudgmentSequenceProbabilities(
      { block: 1, counter: 1 },
      2,
      maxRadarSlots,
      null,
      forceBlock
    ),
    [{ probability: 1, outcomes: ["basic:block", "tactic"] }]
  );
  assert.throws(
    () => buildRadarJudgmentSequenceProbabilities(
      { block: 1, counter: 1, energyDevice: 1 },
      3,
      maxRadarSlots,
      [forceBlock, null, null]
    ),
    /slotCount 3 超过领域上限 2/
  );
  assert.deepEqual(
    buildRadarJudgmentSequenceProbabilities(
      { assault: 1 },
      2,
      maxRadarSlots,
      null,
      { block: 0, otherBasic: 0, equipment: 0 }
    ),
    [{ probability: 1, outcomes: ["tactic", "tactic"] }]
  );
  assert.deepEqual(
    buildRadarJudgmentSequenceProbabilities(counts, 0, maxRadarSlots),
    [{ probability: 1, outcomes: [] }]
  );
  assert.deepEqual(counts, snapshot);
  assert.equal(sequence.some((branch) => "conditions" in branch || "state" in branch), false);
});



test("AI·雷达：敌方雷达动态免伤按阵营符号反向计入己方效用", () => {
  const { game }
    = makeGame([
      makePlayer("radar-enemy-viewer", 0, "dawn"),
      makePlayer("radar-enemy-target", 1, "dusk")
    ]);
  const evaluator = game.aiController.evaluator,
    counts = { counter: 20, shockwave: 10, assault: 3, recover: 1, defenseDevice: 1 },
    viewer = {
      id: "radar-enemy-viewer",
      seatIndex: 0,
      battleTeam: "dawn",
      characterId: "shade-agent",
      alive: true,
      hp: 4,
      maxHp: 4,
      shield: 0,
      energy: 0,
      handCount: 1,
      expectedAssaultCount: 1,
      assaultResponseProbability: 1,
      hand: [],
      attackRange: 1,
      expectedEquipmentGain: 0,
      expectedEquipmentRoleDelta: 0,
      huntMarkProbabilities: {},
      exposeWeaknessStacks: 0,
      statuses: [],
      expectedInformationGain: 0
    },
    enemy = (radar) => ({
      id: "radar-enemy-target",
      seatIndex: 1,
      battleTeam: "dusk",
      characterId: "blade-walker",
      alive: true,
      hp: 4,
      maxHp: 4,
      shield: 0,
      energy: 0,
      handCount: 1,
      expectedAssaultCount: 1,
      assaultResponseProbability: 1,
      attackRange: 1,
      expectedEquipmentGain: 0,
      expectedEquipmentRoleDelta: 0,
      huntMarkProbabilities: {},
      exposeWeaknessStacks: 0,
      statuses: [],
      expectedInformationGain: 0,
      ...(radar
        ? {
          equipmentDefinitionId: "defenseDevice",
          equipmentRetentionProbability: 1,
          initialEquipmentValue: getBaseCardAiValue("defenseDevice"),
          initialEquipmentRoleDelta: 0
        }
        : {
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          initialEquipmentValue: getBaseCardAiValue("defenseDevice"),
          initialEquipmentRoleDelta: 0
        })
    }),
    radarScore = evaluator.stateUtility(
      { remainingCardCounts: counts, players: [viewer, enemy(true)] },
      "radar-enemy-viewer"
    ),
    noRadarScore = evaluator.stateUtility(
      { remainingCardCounts: counts, players: [viewer, enemy(false)] },
      "radar-enemy-viewer"
    );
  // 敌方雷达降低敌方预期受损 → 己方效用更低；差值包含静态 2.25 与按符号反向的动态免伤
  assert.ok(noRadarScore > radarScore);
  assert.ok(noRadarScore - radarScore > statePointsToUtility(9 * .25));
});


