test("AI·影客：窥隙按未知位置选择且只更新自己的私密记忆", async () => {
  const shade = makePlayer("peek-ai", 0, "dawn", "ai", 3),
    ally = makePlayer("peek-ai-ally", 1, "dawn", "ai", 0),
    target = makePlayer("peek-ai-target", 2, "dusk");
  let definitionReads = 0;
  const cards = [instance("counter"), instance("harvest"), instance("duel")];
  for (const card of cards) {
    const value = card.definitionId;
    Object.defineProperty(
      card, "definitionId", { configurable: true, get() { definitionReads += 1; return value; } }
    );
  }
  target.hand.push(...cards);
  const { game, ui }
    = makeGame([shade, ally, target], { random: () => 0 });
  registerPassiveSkills(game);
  await game.damage(shade, target, 1, { canBlock: false });
  assert.equal(definitionReads, 2);
  assert.deepEqual(
    Object.keys(shade.aiMemory.knownCardsByPlayer[target.id]), cards.slice(0, 2).map((card) => card.id)
  );
  assert.equal(Object.keys(ally.aiMemory.knownCardsByPlayer[target.id] ?? {}).length, 0);
  assert.equal(ui.reveals.length, 0);
});






