// ---- AI 评分·转移评分 ----

const TRANSFER_TEST_EVALUATOR = new Evaluator();

/*
功能
通过 Generator 枚举并由 Evaluator 比较一个明确 source/receiver 对的转移资源。

调用方
AI 转移评分与隐藏身份回归测试。

输入
行动者、来源、接收者、排除 ID 与 remaining-card counts。

输出
最佳 canonical Action 的 Evaluator preference。

读取状态
只读测试 fixture。

写入状态
无。

调用函数
Generator.getHandSelections、createAction、Evaluator.compareCandidates/evaluateTransferAction。

边界与不变量
测试 helper 不生成 source/receiver，也不读取未知实体牌面；资源空间只来自 Generator。
*/
function chooseTransferHandCandidate(
  actor,
  from,
  receiver,
  excludedCardIds = null,
  remainingCardCounts = null
) {
  const projectPlayer = (player) => {
    if (player.id === actor.id || !Array.isArray(player.hand)) return player;
    const remembered = actor.aiMemory?.knownCardsByPlayer?.[player.id] ?? {};
    return {
      ...player,
      hand: undefined,
      handCount: player.hand.length,
      knownCards: Array.isArray(player.knownCards)
        ? player.knownCards
        : Object.entries(remembered).map(([cardId, definitionId]) => ({
          cardId,
          definitionId
        }))
    };
  };
  const players = [...new Map(
    [actor, from, receiver].map((player) => [player.id, projectPlayer(player)])
  ).values()];
  const state = upgradeProbabilityFixture({ players, remainingCardCounts });
  const stateActor = state.players.find((player) => player.id === actor.id);
  const stateFrom = state.players.find((player) => player.id === from.id);
  const cardInstanceId = [...(excludedCardIds ?? [])][0] ?? "transfer-test-card";
  const actions = new ActionGenerator().getHandSelections(
    state,
    stateFrom,
    excludedCardIds
  ).map((selection) => createAction({
    type: "card",
    actorId: actor.id,
    cardId: "transfer",
    cardInstanceId,
    selection: { sourceId: from.id, receiverId: receiver.id, ...selection }
  }));
  const selected = actions.reduce((best, action) => {
    if (!best) return action;
    return TRANSFER_TEST_EVALUATOR.compareCandidates(
      { action, valueScore: 0 },
      { action: best, valueScore: 0 },
      stateActor,
      state
    ) > 0 ? action : best;
  }, null);
  return selected
    ? TRANSFER_TEST_EVALUATOR.evaluateTransferAction(selected, stateActor, state)
    : null;
}

/*
功能
把明确的测试 source/receiver/resource 组装为 canonical Action 并交给 Evaluator 评分。

调用方
AI 转移 contextual preference 回归测试。

输入
行动者、来源、接收者、zone、排除 ID 与 remaining-card counts。

输出
Evaluator 返回的 transfer preference。

读取状态
只读测试 fixture 与 CardValue/Evaluator 正式 owner。

写入状态
无。

调用函数
chooseTransferHandCandidate、createAction、Evaluator.evaluateTransferAction。

边界与不变量
仅构造测试所需的单个 canonical Action，不枚举或复制 Domain 合法候选空间。
*/
function evaluateTransferCombinationForTest({
  actor,
  from,
  receiver,
  zone = "hand",
  excludedCardIds = null,
  remainingCardCounts = null
}) {
  const resource = chooseTransferHandCandidate(
    actor,
    from,
    receiver,
    excludedCardIds,
    remainingCardCounts
  );
  const action = createAction({
    type: "card",
    actorId: actor.id,
    cardId: "transfer",
    cardInstanceId: "transfer-test-card",
    selection: {
      sourceId: from.id,
      receiverId: receiver.id,
      zone,
      ...(resource ?? {})
    }
  });
  const players = [...new Map(
    [actor, from, receiver].map((player) => [player.id, player])
  ).values()];
  return TRANSFER_TEST_EVALUATOR.evaluateTransferAction(
    action,
    actor,
    { players, remainingCardCounts }
  );
}

function chooseTransferCombinationForTest(
  game,
  actor,
  card,
  sources,
  allowedReceiverIds = null,
  excludedCardIds = null
) {
  const world = createInitialWorld(
    actor.id,
    game.state,
    deriveCurrentCardCounts(actor, game.state)
  );
  const sourceIds = new Set((sources ?? []).map((source) => source.id));
  const actions = new ActionGenerator().generate(world, actor.id).filter((action) => (
    action.type === "card"
    && action.cardId === "transfer"
    && (!card?.id || action.cardInstanceId === card.id)
    && sourceIds.has(action.selection?.sourceId)
    && (!allowedReceiverIds || allowedReceiverIds.has(action.selection?.receiverId))
    && (!excludedCardIds?.has(action.selection?.cardId))
  ));
  const worldActor = world.players.find((player) => player.id === actor.id);
  const selected = actions.reduce((best, action) => {
    if (!best) return action;
    return TRANSFER_TEST_EVALUATOR.compareCandidates(
      { action, valueScore: 0 },
      { action: best, valueScore: 0 },
      worldActor,
      world
    ) > 0 ? action : best;
  }, null);
  if (!selected) return null;
  const preference = TRANSFER_TEST_EVALUATOR.evaluateTransferAction(
    selected,
    worldActor,
    world
  );
  return preference.score >= MIN_TRANSFER_UTILITY
    ? { ...selected.selection, score: preference.score }
    : null;
}

async function chooseResourceActionForTest(game, actor, card, target) {
  const world = createInitialWorld(
    actor.id,
    game.state,
    deriveCurrentCardCounts(actor, game.state)
  );
  const generatedActions = new ActionGenerator().generate(world, actor.id);
  const roots = generatedActions.filter((action) => (
    action.cardInstanceId === card.id && action.targetIds?.[0] === target.id
  ));
  roots.push(generatedActions.find((action) => action.type === "end"));
  const engine = createSearchEngine({
    world,
    searchConfig: {
      ...game.aiController.buildSearchConfig(),
      depth: 1,
      timeBudgetMs: 10000,
      nodeBudget: 1000
    }
  }, { next: () => 0 });
  return engine.searcher.search(
    world.players.find((player) => player.id === actor.id),
    world,
    roots,
    { gameId: game.state.gameId, rootCandidateCount: roots.length }
  );
}

/*
功能
把 canonical resource selection 绑定回当前真实手牌实体。

调用方
Transfer 规划/执行一致性测试。

输入
测试 Game、行动者、资源拥有者与 Generator/Evaluator 已选 selection。

输出
仍位于合法区域的真实 Card，无法重绑时为 null。

读取状态
HiddenCardChoiceWorkflow 当前实体位置与匿名位置随机源。

写入状态
仅消费测试随机源；不修改牌区。

调用函数
HiddenCardChoiceWorkflow.choosePlayerZoneCard。

边界与不变量
不得重新枚举、模拟或评价候选；这里只执行 Controller 允许的 physical binding。
*/
async function bindCanonicalZoneSelectionForTest(game, actor, owner, selection) {
  return (await game.choosePlayerZoneCard(
    actor,
    owner,
    "测试",
    selection
  ))?.card ?? null;
}

test("AI·转移评分：Generator canonical Action 只由 Evaluator 评分", () => {
  const actor = {
    id: "a", seatIndex: 0, battleTeam: "dawn", characterId: "blade-walker",
    hp: 2, maxHp: 4, alive: true, handCount: 0, aiMemory: { knownCardsByPlayer: {} }
  };
  const source = {
    id: "e", seatIndex: 1, battleTeam: "dusk", characterId: "spirit-medic",
    hp: 2, maxHp: 4, alive: true, handCount: 1,
    knownCards: [{ cardId: "known", definitionId: "recover" }]
  };
  const resource = chooseTransferHandCandidate(actor, source, actor);
  const action = createAction({
    type: "card",
    actorId: actor.id,
    cardId: "transfer",
    cardInstanceId: "canonical-transfer",
    selection: { sourceId: source.id, receiverId: actor.id, zone: "hand", ...resource }
  });
  const state = { players: [actor, source], remainingCardCounts: null };
  const preference = TRANSFER_TEST_EVALUATOR.evaluateTransferAction(action, actor, state);
  assert.equal(preference.cardId, resource.cardId);
  assert.equal(preference.score, resource.score);
});

/*
功能
验证 Generator 只排除己方到敌方方向，Evaluator 与 Simulator 仍保留四种 Domain 动作语义。

调用方
当前测试。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
独立 Game fixture、canonical World、Generator Action、手工 canonical Action 与 Evaluator preference。

写入状态
Simulator 只写独立克隆 World。

调用函数
makePlayer、makeGame、createInitialWorld、AIController.getActionCandidates、createAction、Simulator.apply。

边界与不变量
Generator 只禁止 ally-to-enemy；Evaluator 公式和 Simulator physical transfer 不得随候选策略改变。
*/
function transferDirectionMatrixPreservesLegalityAndExecution() {
  const cases = [
    { name: "ally-to-ally", sourceTeam: "dawn", receiverTeam: "dawn", finite: true },
    { name: "ally-to-enemy", sourceTeam: "dawn", receiverTeam: "dusk", finite: false },
    { name: "enemy-to-ally", sourceTeam: "dusk", receiverTeam: "dawn", finite: true },
    { name: "enemy-to-enemy", sourceTeam: "dusk", receiverTeam: "dusk", finite: false }
  ];
  for (const entry of cases) {
    const actor = makePlayer(`${entry.name}-actor`, 0, "dawn"),
      source = makePlayer(`${entry.name}-source`, 1, entry.sourceTeam),
      receiver = makePlayer(`${entry.name}-receiver`, 2, entry.receiverTeam),
      use = instance("transfer"),
      held = instance("block");
    actor.hand.push(use);
    source.hand.push(held);
    const { game } = makeGame([actor, source, receiver]);
    game.rememberPrivateCard(actor, source, held);
    const world = createInitialWorld(actor.id, game.state);
    const actions = game.aiController.getActionCandidates(actor, world)
      .filter((action) => action.cardInstanceId === use.id);
    const generatedAction = actions.find((candidate) => (
      candidate.selection?.sourceId === source.id
      && candidate.selection?.receiverId === receiver.id
    ));
    const generatorAllowsDirection = entry.name !== "ally-to-enemy";
    assert.equal(Boolean(generatedAction), generatorAllowsDirection, entry.name);
    assert.equal(
      actions.some((candidate) => (
        candidate.selection?.sourceId === candidate.selection?.receiverId
      )),
      false
    );
    const action = generatedAction ?? createAction({
      type:"card",
      actorId:actor.id,
      cardId:"transfer",
      cardInstanceId:use.id,
      selection:{
        sourceId:source.id,
        receiverId:receiver.id,
        zone:"hand",
        selectionKind:"known",
        cardId:held.id,
        definitionId:held.definitionId,
        availableUnknownCount:0
      }
    });
    const preference = game.aiController.evaluator.evaluateTransferAction(
      action,
      world.players.find((player) => player.id === actor.id),
      world
    );
    assert.equal(Number.isFinite(preference.score), entry.finite);
    const after = new Simulator(world).apply(world, action, actor.id);
    assert.equal(after.players.find((player) => player.id === source.id).handCount, 0);
    assert.equal(after.players.find((player) => player.id === receiver.id).handCount, 1);
  }
}

test(
  "AI·转移评分：Generator 单向过滤且四方向评分与 physical transition 保持原语义",
  transferDirectionMatrixPreservesLegalityAndExecution
);

/*
功能
验证 main-thread 与 Worker composition 对同一 canonical Transfer Action 使用完全相同的 Evaluator 语义。

调用方
当前测试。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
同一 canonical World、Action 与两端 Evaluator 实例。

写入状态
无。

调用函数
createSearchEngine、Evaluator.evaluateTransferAction。

边界与不变量
Worker 不得回退旧 TransferPolicy，也不得形成第二套 transfer score 或 tie semantics。
*/
function transferMainWorkerEvaluatorParity() {
  const actor = makePlayer("transfer-parity-actor", 0, "dawn"),
    source = makePlayer("transfer-parity-source", 1, "dusk"),
    receiver = makePlayer("transfer-parity-receiver", 2, "dawn"),
    use = instance("transfer"),
    held = instance("counter");
  actor.hand.push(use);
  source.hand.push(held);
  const { game } = makeGame([actor, source, receiver]);
  game.rememberPrivateCard(actor, source, held);
  const world = createInitialWorld(
    actor.id,
    game.state,
    deriveCurrentCardCounts(actor, game.state)
  );
  const action = game.aiController.getActionCandidates(actor, world).find((candidate) => (
    candidate.cardInstanceId === use.id
    && candidate.selection?.sourceId === source.id
    && candidate.selection?.receiverId === receiver.id
  ));
  assert.ok(action);
  const worldActor = world.players.find((player) => player.id === actor.id);
  const mainPreference = game.aiController.evaluator.evaluateTransferAction(
    action,
    worldActor,
    world
  );
  const workerEngine = createSearchEngine({
    world,
    searchConfig: game.aiController.buildSearchConfig()
  }, { next: () => 0 });
  const workerPreference = workerEngine.searcher.evaluator.evaluateTransferAction(
    action,
    worldActor,
    world
  );
  assert.deepEqual(workerPreference, mainPreference);
}

test("AI·Worker 边界：Transfer 使用 main-thread 同一 Evaluator", transferMainWorkerEvaluatorParity);



test("AI·转移评分：破坏按匿名响应期望选择且不读取真实牌面", async () => {
  const a = makePlayer("a", 0, "dawn"), b = makePlayer("b", 1, "dusk");
  const { game }
    = makeGame([a, b], { random: () => 0 });
  const known = instance("block"), unknown = instance("counter");
  let reads = 0;
  const definitionId = unknown.definitionId, aiValue = unknown.aiValue;
  Object.defineProperty(
    unknown, "definitionId", { configurable: true, get() { reads += 1; return definitionId; } }
  );
  Object.defineProperty(
    unknown, "aiValue", { configurable: true, get() { reads += 1; return aiValue; } }
  );
  b.hand = [known, unknown];
  const use = instance("destroy");
  a.hand.push(use);
  game.rememberPrivateCard(a, b, known);
  const action = await chooseResourceActionForTest(game, a, use, b);
  const chosen = await game.choosePlayerZoneCard(a, b, "测试", action.selection);
  assert.equal(reads, 0);
  assert.equal(chosen.zone, "hand");
  assert.equal(chosen.card, unknown);
});

