test("AI·转移评分：真实与深层模拟选择相同来源接收者及候选类型", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    enemy = makePlayer("enemy", 1, "dusk"),
    ally = makePlayer("ally", 2, "dawn");
  const use = instance("transfer"), held = instance("block");
  actor.hand.push(use);
  enemy.hand.push(held);
  const { game }
    = makeGame([actor, enemy, ally]);
  game.rememberPrivateCard(actor, enemy, held);
  const realAction = game.aiController.getActionCandidates(actor)
    .find((entry) => entry.cardInstanceId === use.id);
  const visible = createInitialWorld(actor.id, game.state);
  const simAction = game.aiController.actionGenerator.generate(
    visible, actor.id
  ).find((entry) => entry.cardInstanceId === use.id);
  assert.ok(realAction);
  assert.ok(simAction);
  assert.equal(realAction.selection.sourceId, simAction.selection.sourceId);
  assert.equal(realAction.selection.receiverId, simAction.selection.receiverId);
  const realCandidate = chooseTransferHandCandidate(actor, enemy, ally);
  const simFrom = visible.players.find((player) => player.id === enemy.id);
  const simAlly = visible.players.find((player) => player.id === ally.id);
  const simCandidate = chooseTransferHandCandidate(actor, simFrom, simAlly);
  assert.equal(realCandidate.selectionKind, simCandidate.selectionKind);
  assert.equal(realCandidate.cardId, simCandidate.cardId);
});

