test("AI·转移评分：转移角色权重：characterId 缺失回退全局基础值且非法角色 ID 抛错", () => {
  assert.equal(cardSituationValue("assault", { hp: 4, maxHp: 4 }), getBaseCardAiValue("assault"));
  assert.equal(cardSituationValue("counter", { hp: 4, maxHp: 4 }), getBaseCardAiValue("counter"));
  assert.throws(
    () => cardSituationValue("assault", { characterId: "not-a-character", hp: 4, maxHp: 4 }), /未知角色 ID/
  );
  assert.throws(() => cardSituationValue("not-a-card", { hp: 4, maxHp: 4 }), /未知卡牌 ID/);
});

test("AI·转移评分：转移角色权重：根节点规划与实际选牌使用同一剩余计数选择相同候选", async () => {
  const actor = makePlayer("actor", 0, "dawn"),
    from = makePlayer("from", 1, "dusk"),
    receiver = makePlayer("receiver", 2, "dawn");
  const use = instance("transfer"), known = instance("assault"), unknown = instance("counter");
  actor.hand.push(use);
  from.hand = [known, unknown];
  const { game }
    = makeGame([actor, from, receiver], { random: () => 0 });
  game.rememberPrivateCard(actor, from, known);
  const counts = deriveCurrentCardCounts(actor, game.state);
  const plan = chooseTransferCombinationForTest(
    game,
    actor,
    use,
    [from],
    new Set([receiver.id])
  );
  assert.ok(plan);
  const world = createInitialWorld(actor.id, game.state, counts);
  const plannedAction = new ActionGenerator().generate(world, actor.id).find((action) => (
    action.cardInstanceId === use.id
    && action.selection?.sourceId === plan.sourceId
    && action.selection?.receiverId === plan.receiverId
    && action.selection?.selectionKind === plan.selectionKind
    && action.selection?.cardId === plan.cardId
  ));
  assert.ok(plannedAction);
  const preference = TRANSFER_TEST_EVALUATOR.evaluateTransferAction(
    plannedAction,
    world.players.find((player) => player.id === actor.id),
    world
  );
  assert.equal(plan.score, preference.score);
  const chosen = await bindCanonicalZoneSelectionForTest(game, actor, from, plan);
  assert.equal(chosen, plan.selectionKind === "known" ? known : unknown);
});

test("AI·转移评分：转移角色权重：深层规划使用可见快照剩余计数", () => {
  const makeState = (counts) => (
    upgradeProbabilityFixture({
      playPhaseEnded: false,
      phase: "play",
      remainingCardCounts: counts,
      players: [
        {
          id: "a",
          seatIndex: 0,
          battleTeam: "dawn",
          characterId: "blade-walker",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 1,
          hand: [{ id: "use", definitionId: "transfer" }],
          attackRange: 1,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          counterProbability: 0
        },
        {
          id: "f",
          seatIndex: 1,
          battleTeam: "dusk",
          characterId: "oath-warden",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 1,
          knownCards: [],
          attackRange: 1,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          counterProbability: 0
        },
        {
          id: "r",
          seatIndex: 2,
          battleTeam: "dawn",
          characterId: "spirit-medic",
          alive: true,
          hp: 4,
          maxHp: 4,
          shield: 0,
          energy: 0,
          handCount: 0,
          attackRange: 1,
          equipmentDefinitionId: null,
          equipmentRetentionProbability: 0,
          counterProbability: 0
        }
      ]
    })
  );
  const actor = makePlayer("real", 0, "dawn"), enemy = makePlayer("other", 1, "dusk");
  const { game }
    = makeGame([actor, enemy]);
  const generator = game.aiController.actionGenerator;
  const assaultState = makeState({ assault: 10 }), recoverState = makeState({ recover: 10 });
  const findTransferToReceiver = (state) => generator.generate(state, "a").find((entry) => (
    entry.cardId === "transfer"
    && entry.selection?.sourceId === "f"
    && entry.selection?.receiverId === "r"
    && entry.selection?.selectionKind === "unknown"
  ));
  const assaultAction = findTransferToReceiver(assaultState);
  const recoverAction = findTransferToReceiver(recoverState);
  assert.ok(assaultAction);
  assert.ok(recoverAction);
  assert.deepEqual(assaultAction.selection, recoverAction.selection);
  const assaultPreference = TRANSFER_TEST_EVALUATOR.evaluateTransferAction(
    assaultAction,
    assaultState.players[0],
    assaultState
  );
  const recoverPreference = TRANSFER_TEST_EVALUATOR.evaluateTransferAction(
    recoverAction,
    recoverState.players[0],
    recoverState
  );
  assert.notEqual(assaultPreference.expectedValue, recoverPreference.expectedValue);
  assert.notEqual(assaultPreference.score, recoverPreference.score);
  const assaultCandidate = chooseTransferHandCandidate(
    assaultState.players[0],
    assaultState.players[1],
    assaultState.players[2],
    null,
    assaultState.remainingCardCounts
  );
  const recoverCandidate = chooseTransferHandCandidate(
    recoverState.players[0],
    recoverState.players[1],
    recoverState.players[2],
    null,
    recoverState.remainingCardCounts
  );
  assert.equal(assaultCandidate.selectionKind, "unknown");
  assert.equal(assaultCandidate.expectedValue, getRoleCardAiValue("spirit-medic", "assault"));
  assert.equal(recoverCandidate.selectionKind, "unknown");
  assert.equal(recoverCandidate.expectedValue, getRoleCardAiValue("spirit-medic", "recover") - 2);
});

test("AI·转移评分：转移动作携带已知候选身份", () => {
  const actor = makePlayer("actor", 0, "dawn"),
    enemy = makePlayer("enemy", 1, "dusk"),
    ally = makePlayer("ally", 2, "dawn");
  const use = instance("transfer"), held = instance("block");
  actor.hand.push(use);
  enemy.hand.push(held);
  const { game }
    = makeGame([actor, enemy, ally]);
  game.rememberPrivateCard(actor, enemy, held);
  const world = createInitialWorld(actor.id, game.state);
  const action = game.aiController.getActionCandidates(actor, world).find((entry) => (
    entry.cardInstanceId === use.id
    && entry.selection?.sourceId === enemy.id
    && entry.selection?.receiverId === ally.id
    && entry.selection?.cardId === held.id
  ));
  assert.ok(action);
  const selection = action.selection;
  assert.equal(selection.selectionKind, "known");
  assert.equal(selection.cardId, held.id);
  assert.equal(selection.definitionId, "block");
  assert.equal(selection.availableUnknownCount, 0);
  assert.equal(Object.hasOwn(selection, "expectedValue"), false);
  assert.equal(Object.hasOwn(selection, "score"), false);
  const preference = game.aiController.evaluator.evaluateTransferAction(
    action,
    world.players.find((player) => player.id === actor.id),
    world
  );
  assert.equal(preference.expectedValue, getRoleCardAiValue("spirit-medic", "block"));
  assert.ok(Number.isFinite(preference.score));
});

