test("UI·响应窗口：反制链响应说明包含来源、目标、原牌和当前反制", async () => {
  const a = makePlayer("a", 0, "dawn", "human"),
    b = makePlayer("b", 1, "dusk", "human"),
    c = makePlayer("c", 2, "dawn", "human");
  const { game, ui }
    = makeGame(
      [a, b, c], { response: (request) => request.legalCardIds.length >= request.requiredCount }
    );
  a.hand.push(instance("harvest"));
  b.hand.push(instance("counter"));
  c.hand.push(instance("counter"));
  await game.playCard(a, a.hand[0], []);
  const chained = ui.responseRequests.find(
    (request) => request.type === "counter" && request.sourcePlayerId === b.id && request.targetPlayerId === c.id
  );
  assert.ok(chained);
  assert.match(chained.presentation.eventText, new RegExp(`${b.name}.*${a.name}.*丰收.*反制`));
  assert.match(chained.presentation.responseText, /继续.*反制/);
});

