test("UI·响应窗口：反制链与濒死响应片段保留实际角色身份", () => {
  const responder = { id: "responder", name: "角色C", battleTeam: "dawn" },
    source = { id: "source", name: "角色B", battleTeam: "dusk" },
    previous = { id: "previous", name: "角色A", battleTeam: "dawn" };
  const chain = buildResponsePresentation(
    responder,
    "counter",
    {
      source, target: previous, targets: [previous], card: instance("counter"), counteredCardName: "丰收"
    },
    1,
    0,
    "反制"
  );
  assert.equal(chain.eventText, "角色B对角色A打出的「丰收」使用了「反制」。");
  assert.deepEqual(
    chain.eventFragments,
    [
      { type: "player", text: "角色B", playerId: "source", battleTeam: "dusk" },
      { type: "text", text: "对" },
      { type: "player", text: "角色A", playerId: "previous", battleTeam: "dawn" },
      { type: "text", text: "打出的「丰收」使用了「反制」。" }
    ]
  );
  const dying = buildResponsePresentation(
    responder, "dyingRescue", { target: previous }, 1, 0, "使用调息"
  );
  assert.equal(dying.eventText, "角色A已进入濒死状态。");
  assert.deepEqual(
    dying.eventFragments,
    [
      { type: "player", text: "角色A", playerId: "previous", battleTeam: "dawn" },
      { type: "text", text: "已进入濒死状态。" }
    ]
  );
  const selfDying = buildResponsePresentation(
    responder, "dyingRescue", { target: responder }, 1, 0, "使用调息"
  );
  assert.equal(selfDying.eventText, "你已进入濒死状态。");
  assert.deepEqual(
    selfDying.eventFragments, [{ type: "text", text: "你" }, { type: "text", text: "已进入濒死状态。" }]
  );
});

