test("UI·互利选择：互利必须先选择再确认且可直接切换选择", async () => {
  const element = makeInteractiveElement(),
    view = new PublicPoolView(element),
    player = makePlayer("human", 0, "dawn", "human"),
    first = instance("assault"),
    second = instance("block");
  let settled = false;
  const pending = view.request(player, [first, second]).then((card) => {
    settled = true;
    return card;
  });
  assert.match(element.innerHTML, /data-public-confirm disabled/);
  element.click(clickTarget("[data-public-card-id]", { publicCardId: first.id }));
  await Promise.resolve();
  assert.equal(settled, false);
  assert.equal(view.pending.selected.has(first.id), true);
  assert.doesNotMatch(element.innerHTML, /data-public-confirm disabled/);
  element.click(clickTarget("[data-public-card-id]", { publicCardId: second.id }));
  assert.deepEqual([...view.pending.selected], [second.id]);
  assert.equal(settled, false);
  element.click(clickTarget("[data-public-confirm]"));
  assert.equal(await pending, second);
  assert.equal(view.pending, null);
});

