test("UI·结束页面：结束时保留现有日志且进入下一局选择时才清空", async () => {
  const winner = makePlayer("winner", 0, "dawn"), defeated = makePlayer("defeated", 1, "dusk");
  const { game, ui } = makeGame([winner, defeated]);
  game.log("首回合开始。");
  defeated.alive = false;
  await game.checkVictory();
  const finalLog = game.state.logs.at(-1);
  assert.match(finalLog.message, /晨星阵营消灭了全部敌人，获得胜利/);
  assert.equal(ui.logs.at(-1), finalLog.message);

  const overlayClasses = new Set(["is-hidden"]);
  const overlay = {
    classList: {
      add: (name) => overlayClasses.add(name),
      remove: (name) => overlayClasses.delete(name)
    }
  };
  const authoritativeLogMarkup = game.state.logs.map((entry) => `<div>${formatLogEntry(entry)}</div>`).join("");
  const logList = { innerHTML: authoritativeLogMarkup, scrollTop: 37 };
  const title = { textContent: "" }, copy = { textContent: "" };
  UIManager.prototype.showGameOver.call({
    elements: { game_over_title: title, game_over_copy: copy, game_over_overlay: overlay }
  }, "dawn", true);
  assert.equal(logList.innerHTML, authoritativeLogMarkup);
  assert.equal(logList.scrollTop, 37);
  assert.equal(overlayClasses.has("is-hidden"), false);
  assert.equal(title.textContent, "你的阵营获胜");
  assert.match(copy.textContent, /晨星阵营存活到了最后/);

  let visibleLogCount = 2;
  const classList = { add() { }, remove() { } };
  UIManager.prototype.showSelection.call({
    sound: { playSquadSelectionMusic() { } },
    cancelPendingInteractions() { },
    resetCurrentCard() { },
    clearLog() {
      logList.innerHTML = "";
      logList.scrollTop = 0;
      visibleLogCount = 0;
    },
    elements: {
      start_screen: { classList }, squad_selection_screen: { classList }, game_screen: { classList },
      selection_screen: { classList }, game_over_overlay: overlay,
      selection_eyebrow: { textContent: "" }, selection_title: { textContent: "" },
      selection_copy: { textContent: "" }, team_preview: { innerHTML: "" },
      candidate_grid: { innerHTML: "" }
    }
  }, [], "random");
  assert.equal(logList.innerHTML, "");
  assert.equal(logList.scrollTop, 0);
  assert.equal(visibleLogCount, 0);
  assert.equal(overlayClasses.has("is-hidden"), true);
});

/*
功能
验证 UI adapter 将公开结算来源映射为正确 VFX 变体。

调用方
当前测试。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
无。

写入状态
本地 queued 记录。

调用函数
createGamePresentationAdapter、PresentationPort feedback 方法。

边界与不变量
护盾获得与伤害吸收必须保持不同展示语义。
*/
function frVfxAdapterMapping() {
  const queued = [];
  const presentation = createGamePresentationAdapter({
    log: () => { },
    getPlayerById: () => null,
    getCardById: () => null,
    ui: {
      queueFeedback: (...args) => queued.push(args),
      render: () => { }
    },
    renderTarget: {}
  });
  for (const [effectDefinitionId, variant] of [
    ["assault", "slash"],
    ["shockwave", "explosion"],
    ["provoke", "red-impact"],
    ["duel", "cross-slash"],
    ["hunt", "hunt"],
    ["burningField", "burning-field"]
  ]) {
    presentation.showDamageFeedback("target", 1, effectDefinitionId, "normal");
    assert.deepEqual(queued.at(-1), ["damage", "target", 1, variant]);
  }
  presentation.showMitigationFeedback("target", 1, "guardianAid");
  assert.deepEqual(queued.at(-1), ["mitigation", "target", 1, "guardian-aid"]);
  presentation.showShieldFeedback("target", 2, "gain");
  presentation.showShieldFeedback("target", -1, "absorb");
  presentation.showHealFeedback("target", 1);
  assert.deepEqual(queued.slice(-3), [
    ["shield", "target", 2, "gain"],
    ["shield", "target", -1, "absorb"],
    ["heal", "target", 1]
  ]);
}

test("UI·结算特效：adapter 统一映射伤害、护援减伤与护盾反馈", frVfxAdapterMapping);

/*
功能
验证真实卡牌与 CombatWorkflow 只为实际生效目标提交对应结算反馈。

调用方
当前测试。

输入
无。

输出
Promise<void>，断言失败时拒绝。

读取状态
独立 makeGame fixtures 的生命、手牌与 presentation 队列。

写入状态
各 fixture 按正式卡牌 workflow 完成结算。

调用函数
Game.playCard、Game.heal、makeGame。

边界与不变量
反制目标、0 治疗和决斗胜者不得收到成功受击/治疗反馈。
*/
async function frVfxRealResolutionFeedback() {
  {
    const source = makePlayer("vfx-assault-source", 0, "dawn"),
      target = makePlayer("vfx-assault-target", 1, "dusk"),
      { game, ui } = makeGame([source, target]),
      feedback = [];
    ui.queueFeedback = (...args) => feedback.push(args);
    const card = instance("assault");
    source.hand.push(card);
    await game.playCard(source, card, [target]);
    assert.ok(feedback.some((entry) => entry[0] === "damage" && entry[1] === target.id && entry[3] === "slash"));
  }
  {
    const source = makePlayer("vfx-shockwave-source", 0, "dawn"),
      countered = makePlayer("vfx-shockwave-countered", 1, "dusk", "human"),
      damaged = makePlayer("vfx-shockwave-damaged", 2, "dusk"),
      { game, ui } = makeGame([source, countered, damaged], {
        response: (request) => request.type === "counter" && request.targetPlayerId === countered.id
      }),
      feedback = [];
    ui.queueFeedback = (...args) => feedback.push(args);
    const card = instance("shockwave");
    source.hand.push(card);
    countered.hand.push(instance("counter"));
    await game.playCard(source, card, [countered, damaged]);
    const explosions = feedback.filter((entry) => entry[0] === "damage" && entry[3] === "explosion");
    assert.deepEqual(explosions.map((entry) => entry[1]), [damaged.id]);
  }
  {
    const source = makePlayer("vfx-provoke-source", 0, "dawn"),
      target = makePlayer("vfx-provoke-target", 1, "dusk"),
      { game, ui } = makeGame([source, target]),
      feedback = [];
    ui.queueFeedback = (...args) => feedback.push(args);
    const card = instance("provoke");
    source.hand.push(card);
    await game.playCard(source, card, [target]);
    assert.ok(feedback.some((entry) => entry[0] === "damage" && entry[1] === target.id && entry[3] === "red-impact"));
  }
  {
    const source = makePlayer("vfx-duel-source", 0, "dawn"),
      target = makePlayer("vfx-duel-target", 1, "dusk"),
      { game, ui } = makeGame([source, target]),
      feedback = [];
    ui.queueFeedback = (...args) => feedback.push(args);
    const card = instance("duel");
    source.hand.push(card);
    await game.playCard(source, card, [target]);
    assert.ok(feedback.some((entry) => entry[0] === "damage" && entry[1] === target.id && entry[3] === "cross-slash"));
    assert.equal(feedback.some((entry) => entry[0] === "damage" && entry[1] === source.id), false);
  }
  {
    const healer = makePlayer("vfx-healer", 0, "dawn"),
      target = makePlayer("vfx-heal-target", 1, "dawn"),
      enemy = makePlayer("vfx-heal-enemy", 2, "dusk"),
      { game, ui } = makeGame([healer, target, enemy]),
      feedback = [];
    ui.queueFeedback = (...args) => feedback.push(args);
    assert.equal(await game.heal(healer, target, 1), 0);
    assert.equal(feedback.some((entry) => entry[0] === "heal"), false);
    target.hp -= 1;
    assert.equal(await game.heal(healer, target, 1), 1);
    assert.ok(feedback.some((entry) => entry[0] === "heal" && entry[1] === target.id));
  }
  {
    const source = makePlayer("vfx-shield-source", 0, "dawn"),
      enemy = makePlayer("vfx-shield-enemy", 1, "dusk"),
      { game, ui } = makeGame([source, enemy]),
      feedback = [];
    ui.queueFeedback = (...args) => feedback.push(args);
    const card = instance("shield");
    source.hand.push(card);
    await game.playCard(source, card, [source]);
    assert.ok(feedback.some((entry) => entry[0] === "shield" && entry[1] === source.id && entry[3] === "gain"));
    await game.damage(enemy, source, 1, { canBlock: false });
    assert.ok(feedback.some((entry) => entry[0] === "shield"
      && entry[1] === source.id && entry[2] === -1 && entry[3] === "absorb"));
  }
  {
    const player = makePlayer("vfx-energy-target", 0, "dawn"),
      enemy = makePlayer("vfx-energy-enemy", 1, "dusk"),
      { game, ui } = makeGame([player, enemy]),
      feedback = [];
    ui.queueFeedback = (...args) => feedback.push(args);
    player.energy = 0;
    player.maxEnergy = 4;
    assert.equal(await game.gainEnergy(player, 2, { reason: "回合开始" }), 2);
    assert.ok(feedback.some((entry) => entry[0] === "energy"
      && entry[1] === player.id && entry[2] === 2));
    player.energy = player.maxEnergy;
    const feedbackCount = feedback.length;
    assert.equal(await game.gainEnergy(player, 2, { reason: "测试" }), 0);
    assert.equal(feedback.length, feedbackCount, "能量到达上限后不得提交 +0 或成功 VFX");
    player.energy = 0;
    const charge = instance("charge");
    player.hand.push(charge);
    await game.playCard(player, charge, []);
    assert.ok(feedback.slice(feedbackCount).some((entry) => entry[0] === "energy"
      && entry[1] === player.id && entry[2] === 1));
  }
}

test("UI·结算特效：真实卡牌结算只向实际目标提交对应反馈", frVfxRealResolutionFeedback);

/*
功能
验证猎杀与焚场只为实际生命伤害提交技能 VFX，且焚场反馈保持真实目标结算顺序。

调用方
当前测试。

输入
无。

输出
Promise<void>，断言失败时拒绝。

读取状态
独立 makeGame fixtures 的技能、格挡响应、生命与 presentation 队列。

写入状态
各 fixture 按正式技能 workflow 完成结算。

调用函数
Game.useActiveSkill、makeGame。

边界与不变量
格挡目标不得提交成功 VFX；焚场受伤反馈不得脱离 getEnemies 的真实结算顺序。
*/
async function frSkillVfxRealResolutionFeedback() {
  {
    const hunter = makePlayer("vfx-hunt-source", 0, "dawn", "ai", 5),
      target = makePlayer("vfx-hunt-target", 1, "dusk", "human"),
      { game, ui } = makeGame([hunter, target]),
      feedback = [];
    hunter.energy = 2;
    target.statuses.huntMark = { sourceId: hunter.id };
    ui.queueFeedback = (...args) => feedback.push(args);
    assert.equal(await game.useActiveSkill(hunter, "hunt", [target]), true);
    assert.ok(feedback.some((entry) => entry[0] === "damage"
      && entry[1] === target.id && entry[3] === "hunt"));
  }
  {
    const hunter = makePlayer("vfx-blocked-hunt-source", 0, "dawn", "ai", 5),
      target = makePlayer("vfx-blocked-hunt-target", 1, "dusk", "human"),
      { game, ui } = makeGame([hunter, target], {
        response: (request) => request.type === "block" && request.targetPlayerId === target.id
      }),
      feedback = [];
    hunter.energy = 2;
    target.statuses.huntMark = { sourceId: hunter.id };
    target.hand.push(instance("block"));
    ui.queueFeedback = (...args) => feedback.push(args);
    assert.equal(await game.useActiveSkill(hunter, "hunt", [target]), true);
    assert.equal(feedback.some((entry) => entry[0] === "damage" && entry[3] === "hunt"), false);
  }
  {
    const ember = makePlayer("vfx-field-source", 0, "dawn", "human", 4),
      blocked = makePlayer("vfx-field-blocked", 1, "dusk", "human"),
      damagedA = makePlayer("vfx-field-damaged-a", 2, "dusk"),
      damagedB = makePlayer("vfx-field-damaged-b", 3, "dusk"),
      damagedC = makePlayer("vfx-field-damaged-c", 4, "dusk"),
      { game, ui } = makeGame([ember, blocked, damagedA, damagedB, damagedC], {
        response: (request) => request.type === "block" && request.targetPlayerId === blocked.id
      }),
      feedback = [];
    ember.energy = 3;
    blocked.hand.push(instance("block"));
    ui.queueFeedback = (...args) => feedback.push(args);
    assert.equal(await game.useActiveSkill(ember, "burningField", []), true);
    const burningHits = feedback.filter((entry) => entry[0] === "damage"
      && entry[3] === "burning-field");
    assert.deepEqual(burningHits.map((entry) => entry[1]), [damagedA.id, damagedB.id, damagedC.id]);
  }
}

test("UI·结算特效：猎杀与焚场仅对实际受伤目标提交技能反馈", frSkillVfxRealResolutionFeedback);

