test("UI·闪电反馈：电弧 overlay 跟随人物框、可重复触发并完整清理", () => {
  const makeClassList = (initial = []) => {
    const values = new Set(initial);
    return { add: (name) => values.add(name), remove: (name) => values.delete(name), contains: (name) => values.has(name) };
  };
  const makeElement = (className = "") => {
    const children = [];
    const listeners = new Map();
    const styleValues = new Map();
    const element = {
      className,
      classList: makeClassList(className ? className.split(" ") : []),
      children,
      isConnected: true,
      owner: null,
      style: {
        setProperty: (name, value) => styleValues.set(name, value),
        getPropertyValue: (name) => styleValues.get(name),
        removeProperty: (name) => styleValues.delete(name)
      },
      setAttribute(name, value) { this[name] = value; },
      getAttribute(name) { return this[name]; },
      addEventListener(type, handler) { listeners.set(type, handler); },
      append(child) { child.owner = this; children.push(child); },
      querySelectorAll(selector) { return selector === ".lightning-hit-overlay" ? children.filter((child) => child.className === "lightning-hit-overlay") : []; },
      remove() {
        this.isConnected = false;
        if (this.owner) this.owner.children.splice(this.owner.children.indexOf(this), 1);
      },
      listeners
    };
    return element;
  };
  const panel = makeElement("player-seat");
  panel.getBoundingClientRect = () => ({ left: 100, top: 200, width: 300, height: 180 });
  const body = makeElement("body");
  const viewListeners = new Map();
  const doc = {
    createElement: () => makeElement(),
    createElementNS: () => makeElement(),
    querySelector: (selector) => selector.includes("hit-player") ? panel : null,
    ownerDocument: null,
    body,
    defaultView: {
      addEventListener: (type, handler) => viewListeners.set(type, handler),
      removeEventListener: (type, handler) => {
        if (viewListeners.get(type) === handler) viewListeners.delete(type);
      }
    }
  };
  const controller = new AnimationController();
  controller.startLightning("hit-player", doc);
  const first = body.children[0];
  assert.equal(first.className, "lightning-hit-overlay");
  assert.equal(first.children.filter((child) => child.getAttribute("class")?.includes("lightning-bolt")).length, 6);
  assert.equal(first.children.filter((child) => child.className.includes("lightning-spark")).length, 10);
  assert.equal(first.children[0].className, "lightning-impact-flash");
  const firstBolt = first.children.find((child) => child.getAttribute("class")?.includes("bolt-top-a"));
  assert.ok(firstBolt.children.some((child) => child.getAttribute("class") === "lightning-bolt-core"));
  assert.ok(firstBolt.children.some((child) => child.getAttribute("class") === "lightning-bolt-branch"));
  assert.equal(first["aria-hidden"], "true");
  assert.equal(first.style.getPropertyValue("--lightning-left"), "90px");
  assert.equal(first.style.getPropertyValue("--lightning-top"), "190px");
  assert.equal(first.style.getPropertyValue("--lightning-width"), "320px");
  assert.equal(first.style.getPropertyValue("--lightning-height"), "200px");
  assert.ok(panel.style.getPropertyValue("--lightning-hit-duration").endsWith("ms"));
  assert.equal(viewListeners.has("resize"), true);
  assert.equal(viewListeners.has("scroll"), true);
  assert.equal(panel.classList.contains("has-lightning-hit"), true);
  const duration = Number.parseInt(first.style.getPropertyValue("--lightning-hit-duration"), 10);
  assert.ok(duration <= LIGHTNING_HIT_DURATION_MS && duration >= LIGHTNING_HIT_DURATION_MS - 20);
  assert.equal(LIGHTNING_HIT_DURATION_MS, 3000);
  controller.startLightning("hit-player", doc);
  assert.equal(first.isConnected, false, "重复命中必须清理旧实例并重启动画");
  assert.equal(body.children.length, 1);
  const second = body.children[0];
  second.listeners.get("animationend")({ target: second, animationName: "lightningHitLifetime" });
  assert.equal(body.children.length, 0, "生命周期动画结束后必须自动移除 overlay");
  assert.equal(panel.classList.contains("has-lightning-hit"), false);
  assert.equal(panel.style.getPropertyValue("--lightning-hit-duration"), undefined);
  assert.equal(controller.activeLightning.size, 0);
  assert.equal(viewListeners.size, 0);
  controller.startLightning("hit-player", doc);
  controller.clear();
  assert.equal(body.children.length, 0);
  assert.equal(controller.activeLightning.size, 0);
});

/*
功能
验证多人结算 overlay、render 后伤害震动续接与统一清理。

调用方
当前测试。

输入
无。

输出
无返回值，断言失败时抛错。

读取状态
fake DOM、AnimationController 展示状态与 UIManager feedback-to-sound 映射。

写入状态
fake DOM overlay、class 与控制器短生命周期记录。

调用函数
UIManager.queueFeedback、UIManager.playFeedbackSound、AnimationController.flush、clear。

边界与不变量
  多个目标可并存；护援复用同一 overlay/cleanup 且不显示数值；新正向 overlay 与 shield loss 不得叠加旧人物框动画；
  每项 feedback 只能在自身展示启动时触发一次声音，同一刷新中的多目标伤害不得串行排队。
*/
function frVfxOverlayLifecycle() {
  const panels = new Map();
  const doc = {
    ownerDocument: null,
    body: null,
    createElement(tagName = "span") {
      const classValues = new Set();
      const styleValues = new Map();
      const listeners = new Map();
      const children = [];
      return {
        tagName: tagName.toUpperCase(),
        className: "",
        classList: {
          add: (...names) => names.forEach((name) => classValues.add(name)),
          remove: (...names) => names.forEach((name) => classValues.delete(name)),
          contains: (name) => classValues.has(name)
        },
        style: {
          setProperty: (name, value) => styleValues.set(name, value),
          getPropertyValue: (name) => styleValues.get(name),
          removeProperty: (name) => styleValues.delete(name)
        },
        children,
        isConnected: true,
        owner: null,
        setAttribute(name, value) { this[name] = value; },
        addEventListener(type, handler) { listeners.set(type, handler); },
        append(child) { child.owner = this; children.push(child); },
        remove() {
          this.isConnected = false;
          if (this.owner) this.owner.children.splice(this.owner.children.indexOf(this), 1);
        },
        listeners
      };
    },
    querySelector(selector) {
      for (const [playerId, panel] of panels) {
        if (selector.includes(playerId)) return panel;
      }
      return selector === ".command-deck" ? this.commandDeck : null;
    }
  };
  doc.body = doc.createElement();
  doc.commandDeck = doc.createElement();
  for (const [playerId, left] of [["target-a", 40], ["target-b", 380], ["target-c", 720]]) {
    const panel = doc.createElement();
    panel.getBoundingClientRect = () => ({ left, top: 120, width: 280, height: 170 });
    panels.set(playerId, panel);
  }

  const sounds = [];
  const ui = { playSound: (name) => sounds.push(name) };
  const controller = new AnimationController(
    (feedback) => UIManager.prototype.playFeedbackSound.call(ui, feedback)
  );
  ui.animationController = controller;
  const queueFeedback = (...args) => UIManager.prototype.queueFeedback.call(ui, ...args);
  queueFeedback("damage", "target-a", 2, "slash");
  queueFeedback("damage", "target-b", 1, "explosion");
  assert.deepEqual(sounds, [], "feedback 入队不得抢在对应动画前播放声音");
  controller.flush(doc);
  assert.deepEqual(sounds, ["hit", "hit"], "非串行多目标的每个实际展示各播放一次 hit");
  assert.equal(doc.body.children.length, 2);
  const slashOverlay = doc.body.children.find((overlay) => overlay.className.includes("is-slash"));
  const explosionOverlay = doc.body.children.find((overlay) => overlay.className.includes("is-explosion"));
  assert.equal(slashOverlay.children[0].className, "floating-feedback is-damage");
  assert.equal(slashOverlay.children[0].textContent, "−2");
  assert.equal(explosionOverlay.children[0].textContent, "−1");
  assert.equal(slashOverlay.style.getPropertyValue("--resolution-vfx-duration"), "800ms");
  assert.equal(controller.activeDamageFeedback.size, 2);
  assert.ok(panels.get("target-a").classList.contains("feedback-damage"));
  assert.ok(panels.get("target-b").classList.contains("feedback-damage"));

  const oldPanel = panels.get("target-a");
  const replacement = doc.createElement();
  replacement.getBoundingClientRect = oldPanel.getBoundingClientRect;
  oldPanel.isConnected = false;
  panels.set("target-a", replacement);
  controller.flush(doc);
  assert.ok(replacement.classList.contains("feedback-damage"), "render 后按剩余时长续接受击震动");

  queueFeedback("heal", "target-a", 1);
  queueFeedback("shield", "target-b", 1, "gain");
  queueFeedback("energy", "target-a", 1);
  queueFeedback("shield", "target-b", -1, "absorb");
  controller.flush(doc);
  const healOverlay = doc.body.children.find((overlay) => overlay.className.includes("is-heal"));
  const shieldOverlay = doc.body.children.find((overlay) => overlay.className.includes("is-shield"));
  const energyOverlay = doc.body.children.find((overlay) => overlay.className.includes("is-energy"));
  const shieldLossOverlay = doc.body.children.find((overlay) => overlay.className === "resolution-vfx-overlay"
    && overlay.children[0]?.className === "floating-feedback is-shield");
  const healVisual = healOverlay.children.find((child) => child.className === "positive-vfx-visual");
  const shieldVisual = shieldOverlay.children.find((child) => child.className === "positive-vfx-visual");
  const energyVisual = energyOverlay.children.find((child) => child.className === "positive-vfx-visual");
  const healIcon = healVisual.children[0];
  const shieldIcon = shieldVisual.children[0];
  const energyIcon = energyVisual.children[0];
  assert.equal(healOverlay.children.find((child) => child.className === "floating-feedback is-heal").textContent, "+1");
  assert.equal(shieldOverlay.children.find((child) => child.className === "floating-feedback is-shield").textContent, "+1");
  assert.equal(energyOverlay.children.find((child) => child.className === "floating-feedback is-energy").textContent, "+1");
  assert.equal(shieldLossOverlay.children[0].textContent, "−1");
  assert.equal(shieldLossOverlay.children.some((child) => child.className === "positive-vfx-visual"), false);
  assert.equal(healOverlay.style.getPropertyValue("--resolution-vfx-duration"), "1000ms");
  assert.equal(shieldOverlay.style.getPropertyValue("--resolution-vfx-duration"), "1000ms");
  assert.equal(energyOverlay.style.getPropertyValue("--resolution-vfx-duration"), "1000ms");
  assert.deepEqual([healIcon.tagName, healIcon.src], ["IMG", CARD_PRESENTATION.recover.glyph]);
  assert.deepEqual([shieldIcon.tagName, shieldIcon.src], ["IMG", CARD_PRESENTATION.shield.glyph]);
  assert.deepEqual([energyIcon.tagName, energyIcon.src], ["IMG", CARD_PRESENTATION.charge.glyph]);
  for (const icon of [healIcon, shieldIcon, energyIcon]) {
    assert.equal(icon["aria-hidden"], "true");
    assert.equal(icon.draggable, "false");
  }
  assert.equal(controller.activeDamageFeedback.size, 2, "治疗、护盾和能量不得创建伤害震动");
  assert.equal(controller.activeResolutionEffects.size, 6);
  assert.equal(panels.get("target-a").classList.contains("feedback-heal"), false);
  assert.equal(panels.get("target-a").classList.contains("feedback-energy"), false);
  assert.equal(panels.get("target-b").classList.contains("feedback-shield"), false);

  queueFeedback("heal", "target-a", 0);
  queueFeedback("energy", "target-a", 0);
  controller.flush(doc);
  assert.equal(doc.body.children.length, 6, "零治疗和零能量不得创建成功 overlay");
  queueFeedback("draw", "target-a");
  controller.flush(doc);
  const drawPanel = panels.get("target-a");
  assert.equal(drawPanel.classList.contains("feedback-draw"), true);
  drawPanel.listeners.get("animationend")();
  assert.equal(drawPanel.classList.contains("feedback-draw"), false);
  queueFeedback("shield", "missing-target", -1, "absorb");
  controller.flush(doc);
  const shieldLossFallback = doc.commandDeck.children[0];
  assert.equal(shieldLossFallback.className, "floating-feedback is-shield");
  assert.equal(shieldLossFallback.textContent, "−1");
  assert.equal(doc.commandDeck.classList.contains("feedback-shield"), false);
  energyOverlay.listeners.get("animationend")({ target: energyOverlay, animationName: "positiveVfxLifetime" });
  assert.equal(energyOverlay.isConnected, false);
  assert.equal(controller.activeResolutionEffects.size, 5, "生命周期动画结束后必须清理对应 overlay");

  controller.clear();
  assert.equal(doc.body.children.length, 0);
  assert.equal(controller.activeDamageFeedback.size, 0);
  assert.equal(controller.activeResolutionEffects.size, 0);
  assert.equal(replacement.classList.contains("feedback-damage"), false);

  sounds.length = 0;
  queueFeedback("damage", "target-a", 2, "hunt");
  assert.deepEqual(sounds, [], "单目标 hit 也必须等待自身表现启动");
  controller.flush(doc);
  assert.deepEqual(sounds, ["hit"], "单目标表现仍播放一次 hit");
  const huntOverlay = doc.body.children.find((overlay) => overlay.className.includes("is-hunt"));
  assert.equal(huntOverlay.style.getPropertyValue("--resolution-vfx-duration"), "720ms");
  assert.ok(replacement.classList.contains("feedback-damage"), "猎杀保留统一受伤震动");
  controller.clear();

  queueFeedback("mitigation", "target-a", 1, "guardian-aid");
  controller.flush(doc);
  let guardianAidOverlay = doc.body.children.find((overlay) => overlay.className.includes("is-guardian-aid"));
  assert.equal(guardianAidOverlay.style.getPropertyValue("--resolution-vfx-duration"), "680ms");
  assert.equal(guardianAidOverlay.children.length, 0, "护援屏障不伪造伤害或护盾数值");
  assert.equal(replacement.classList.contains("feedback-damage"), false);
  guardianAidOverlay.listeners.get("animationend")({
    target: guardianAidOverlay, animationName: "resolutionVfxLifetime"
  });
  assert.equal(guardianAidOverlay.isConnected, false);
  assert.equal(controller.activeResolutionEffects.size, 0);
  queueFeedback("mitigation", "target-a", 1, "guardian-aid");
  controller.flush(doc);
  guardianAidOverlay = doc.body.children.find((overlay) => overlay.className.includes("is-guardian-aid"));
  assert.ok(guardianAidOverlay, "连续护援可创建全新 overlay");
  controller.clear();
  assert.equal(guardianAidOverlay.isConnected, false, "清场不得残留护援 overlay");

  sounds.length = 0;
  queueFeedback("damage", "target-a", 1, "burning-field");
  queueFeedback("damage", "target-b", 1, "burning-field");
  queueFeedback("damage", "target-c", 1, "burning-field");
  assert.deepEqual(sounds, [], "焚场反馈入队时不得抢在表现开始前出声");
  controller.flush(doc);
  assert.deepEqual(sounds, ["hit", "hit", "hit"], "焚场三个目标在同一次表现提交时各触发 hit");
  const burningOverlays = doc.body.children.filter((overlay) => overlay.className.includes("is-burning-field"));
  assert.equal(burningOverlays.length, 3, "焚场多目标的爆燃、数字和受击反馈必须同时开始");
  assert.deepEqual(
    burningOverlays.map((overlay) => overlay.style.getPropertyValue("--resolution-vfx-left")),
    ["30px", "370px", "710px"]
  );
  for (const overlay of burningOverlays) {
    assert.equal(overlay.style.getPropertyValue("--resolution-vfx-duration"), "880ms");
  }
  for (const playerId of ["target-a", "target-b", "target-c"]) {
    assert.equal(panels.get(playerId).classList.contains("feedback-damage"), true);
  }
  controller.clear();
  assert.equal(doc.body.children.length, 0);
}

test("UI·结算特效：signed 数值、多目标同步、SFX 与 overlay 生命周期保持独立", frVfxOverlayLifecycle);

/*
功能
验证三类正向 VFX 使用从对应卡牌主体原样提取的透明 glyph。

调用方
当前测试。

输入
无。

输出
Promise<void>，断言失败时拒绝。

读取状态
CARD_PRESENTATION、三张卡牌 SVG、三个 glyph SVG 与 index.html。

写入状态
无。

调用函数
readFile、正则与集合断言。

边界与不变量
glyph 的每个主体 shape 必须原样存在于对应卡图；不得包含整卡背景，且首次触发前必须预加载。
*/
async function frPositiveVfxGlyphAssets() {
  const index = await readFile(projectFile("index.html"), "utf8");
  for (const [definitionId, glyphName] of [
    ["recover", "recover-glyph.svg"],
    ["shield", "shield-glyph.svg"],
    ["charge", "charge-glyph.svg"]
  ]) {
    const glyphPath = `./assets/ui/${glyphName}`;
    const [card, glyph] = await Promise.all([
      readFile(projectFile(`assets/cards/${definitionId}.svg`), "utf8"),
      readFile(projectFile(`assets/ui/${glyphName}`), "utf8")
    ]);
    assert.equal(CARD_PRESENTATION[definitionId].glyph, glyphPath);
    assert.notEqual(CARD_PRESENTATION[definitionId].glyph, CARD_PRESENTATION[definitionId].icon);
    const shapes = glyph.match(/<(?:path|circle)\b[^>]*\/>/g) ?? [];
    assert.ok(shapes.length > 0, `${glyphName} 必须包含主体 shape`);
    for (const shape of shapes) assert.ok(card.includes(shape), `${glyphName} 含有非卡图来源的 shape`);
    assert.doesNotMatch(glyph, /<rect\b|id="(?:bg|glow|soft)"/i);
    assert.match(index, new RegExp(`rel="preload" href="\\.\\/assets\\/ui\\/${glyphName.replace(".", "\\.")}" as="image"`));
  }
}

