test("UI·布局样式：上方 AI 思考提示出现时隐藏下方重复提示", () => {
  const classes = () => {
    const values = new Set();
    return { values, toggle(name, force) { if (force) values.add(name); else values.delete(name); } };
  };
  const thinkingClasses = classes(), promptClasses = classes();
  const fake = {
    game: null,
    thinkingPlayerId: null,
    thinkingMessage: "",
    elements: {
      thinking_indicator: { classList: thinkingClasses, innerHTML: "" },
      action_prompt: { classList: promptClasses }
    },
    render() { }
  };
  const player = makePlayer("ai", 0, "dawn");
  UIManager.prototype.setThinking.call(fake, true, player, "准备使用突袭");
  assert.ok(promptClasses.values.has("is-hidden"));
  UIManager.prototype.setThinking.call(fake, false, player);
  assert.ok(!promptClasses.values.has("is-hidden"));
});

