test("UI·布局样式：牌面长描述分类确定且真人与已知对手模板共用同一函数", () => {
  for (const definitionId of ["defenseDevice", "transfer", "mutualBenefit", "battleDevice"]) {
    const card = instance(definitionId), descriptionClass = cardDescriptionClass(card.description);
    assert.match(descriptionClass, /^is-description-(?:long|very-long)$/);
    assert.match(handCardTemplate(card), new RegExp(descriptionClass));
    assert.match(opponentHandStripTemplate([{ known: true, ...card }]), new RegExp(descriptionClass));
  }
  for (const definitionId of ["harvest", "counter", "shield", "provoke"]) {
    const card = instance(definitionId);
    assert.equal(cardDescriptionClass(card.description), "");
    assert.doesNotMatch(handCardTemplate(card), /is-description-(?:long|very-long)/);
    assert.doesNotMatch(
      opponentHandStripTemplate([{ known: true, ...card }]), /is-description-(?:long|very-long)/
    );
  }
  assert.equal(
    cardDescriptionClass(CARD_DEFINITIONS.transfer.description), "is-description-very-long"
  );
});

