// ==================== 生命周期、异常与 Cleanup ====================

/*
功能
把 Action authoritative checkpoint 中的 Set/Map 转换为可稳定深比较的数据。

调用方
snapshotAuthoritativeActionState 的 JSON serialization。

输入
JSON replacer key 与当前 value。

输出
Set/Map 的显式数组表示，或原 value。

读取状态
value 的容器内容。

写入状态
无。

调用函数
Array.from。

边界与不变量
只用于测试快照；不读取函数或修改真实实体。
*/
function normalizeActionSnapshotValue(_key, value) {
  if (value instanceof Set) return { $set: [...value] };
  if (value instanceof Map) return { $map: [...value.entries()] };
  return value;
}

/*
功能
捕获一次真实 Action 可观察的 authoritative state 与直接 runtime owner 状态。

调用方
Action atomicity 回归测试。

输入
真实测试 MatchApplication。

输出
可稳定 deepEqual 的独立数据快照。

读取状态
MatchState/Player/Deck、Action/Response/Dying/Card runtime checkpoints 与 PublicCardPool owner。

写入状态
无。

调用函数
JSON.stringify/parse、各 owner checkpoint API。

边界与不变量
函数型 adapter capability 不属于 authoritative state；全部可序列化真实字段、实体顺序、版本与私有 owner 状态必须精确相等。
*/
function snapshotAuthoritativeActionState(game) {
  return JSON.parse(JSON.stringify({
    state: game.state,
    actionState: game.actionWorkflow.getActionStateSnapshot(),
    resolutionOwners: game.actionWorkflow.getResolutionOwnersSnapshot(),
    response: game.responseWorkflow.captureActionCheckpoint(),
    dying: game.dyingWorkflow.captureActionCheckpoint(),
    cardIntent: game.cardIntentRuntime.captureActionCheckpoint(),
    cardEffect: game.cardEffectRuntime.captureActionCheckpoint(),
    publicCardPoolIds: game.publicCardPoolWorkflow.cards.map((card) => card.id)
  }, normalizeActionSnapshotValue));
}

/*
功能
在真实 MatchLogAdapter 与 UIManager 日志边界上运行一次 Action 日志事务场景。

调用方
Action transaction 日志 DOM 一致性回归测试。

输入
run 接收 state、日志 adapter、DOM 替身、计数元素与 transaction factory。

输出
返回 run 的同步结果。

读取状态
无。

写入状态
临时替换 globalThis.document，并写入隔离的日志 state 与 DOM 替身。

调用函数
MatchLogAdapter、UIManager 日志方法、createActionTransaction、createRandomPort。

边界与不变量
每个场景结束后恢复原 document；DOM removeChild 只允许删除当前尾节点。
*/
function withActionLogTransactionFixture(run) {
  const previousDocument = globalThis.document;
  const children = [];
  const list = {
    children,
    lastElementChild: null,
    scrollTop: 0,
    append(node) {
      children.push(node);
      this.lastElementChild = children.at(-1) ?? null;
    },
    removeChild(node) {
      assert.equal(node, children.at(-1));
      const removed = children.pop();
      this.lastElementChild = children.at(-1) ?? null;
      return removed;
    }
  };
  const countElement = {
    textContent: "",
    title: "",
    attributes: new Map(),
    setAttribute(name, value) { this.attributes.set(name, value); }
  };
  const ui = {
    elements: { log_list:list, log_count:countElement },
    logFollowingBottom: false,
    appendLog: UIManager.prototype.appendLog,
    restoreLogBoundary: UIManager.prototype.restoreLogBoundary,
    updateLogCount: UIManager.prototype.updateLogCount
  };
  const state = { players:[], logs:[] };
  const logAdapter = new MatchLogAdapter(state, ui);
  const randomPort = createRandomPort({ next:() => 0.25 });
  globalThis.document = { createElement: () => ({ className:"", innerHTML:"" }) };
  try {
    logAdapter.add("历史日志 A");
    logAdapter.add("历史日志 B");
    return run({
      state,
      logAdapter,
      children,
      countElement,
      createTransaction: () => createActionTransaction({
        roots:[state],
        logs:state.logs,
        restoreLogPresentation: (count) => ui.restoreLogBoundary(count),
        randomPort
      })
    });
  } finally {
    if (previousDocument === undefined) delete globalThis.document;
    else globalThis.document = previousDocument;
  }
}

test("生命周期：Action transaction 不递归 checkpoint 大量历史日志", () => {
  const source = makePlayer("log-boundary-source", 0, "dawn"),
    enemy = makePlayer("log-boundary-enemy", 1, "dusk"),
    card = instance("charge"),
    { game } = makeGame([source, enemy]);
  let historyReads = 0;
  const guardedHistoryEntry = new Proxy({ id:"guarded-history" }, {
    ownKeys() {
      historyReads += 1;
      throw new Error("历史日志不应进入深度 checkpoint");
    }
  });
  game.state.logs.push(
    ...Array.from({ length:5000 }, (_, index) => ({ id:`history-${index}` })),
    guardedHistoryEntry
  );
  source.hand.push(card);
  return game.playCard(source, card, []).then((completed) => {
    assert.equal(completed, true);
    assert.equal(historyReads, 0);
    assert.ok(game.state.logs.length > 5001, "成功 Action 的新增日志必须保留");
  });
});

test("UI·日志：大量追加完整保留且 append 热路径不读取 layout", () => {
  const previousDocument = globalThis.document;
  const nodes = [];
  let layoutReads = 0;
  const list = {
    scrollTop: 0,
    get scrollHeight() {
      layoutReads += 1;
      throw new Error("append 不得读取 scrollHeight");
    },
    append(node) { nodes.push(node); }
  };
  globalThis.document = { createElement: () => ({ className: "", innerHTML: "" }) };
  try {
    const fake = {
      elements: { log_list: list },
      logFollowingBottom: true,
      updateLogCount() { }
    };
    for (let index = 0; index < 2000; index += 1) {
      UIManager.prototype.appendLog.call(
        fake,
        { kind: "normal", message: `日志-${index}` },
        index + 1
      );
    }
    assert.equal(nodes.length, 2000);
    assert.equal(layoutReads, 0);
    assert.equal(list.scrollTop, Number.MAX_SAFE_INTEGER);
  } finally {
    if (previousDocument === undefined) delete globalThis.document;
    else globalThis.document = previousDocument;
  }
});

test("生命周期：Action transaction commit 保留本次新增日志", () => {
  const historicalEntry = { id:"history" };
  const logs = [historicalEntry];
  const state = { logs, player:{ hp:3 } };
  const transaction = createActionTransaction({
    roots:[state],
    logs,
    randomPort:createRandomPort({ next:() => 0.25 })
  });
  const actionEntry = { id:"action-log" };
  logs.push(actionEntry);
  state.player.hp = 2;
  transaction.commit();
  assert.deepEqual(logs, [historicalEntry, actionEntry]);
  assert.equal(state.player.hp, 2);
});

test("生命周期：Action transaction rollback 只删除本次日志并恢复其它状态", () => {
  const historicalEntries = [
    { id:"history-a", nested:{ text:"A" } },
    { id:"history-b", nested:{ text:"B" } }
  ];
  const logs = [...historicalEntries];
  const state = {
    logs,
    player:{ hp:3, statuses:new Set(["sealed"]) },
    deck:{ cards:["card-a", "card-b"] }
  };
  const transaction = createActionTransaction({
    roots:[state],
    logs,
    randomPort:createRandomPort({ next:() => 0.25 })
  });
  logs.push({ id:"action-log-a" }, { id:"action-log-b" });
  state.player.hp = 1;
  state.player.statuses.add("lightning");
  state.deck.cards.shift();
  transaction.rollback();
  assert.deepEqual(logs, historicalEntries);
  assert.equal(logs[0], historicalEntries[0]);
  assert.equal(logs[1], historicalEntries[1]);
  assert.deepEqual(state.player, { hp:3, statuses:new Set(["sealed"]) });
  assert.deepEqual(state.deck.cards, ["card-a", "card-b"]);
});

test("生命周期：Action transaction rollback 同步裁剪多条日志 DOM 与计数", () => {
  withActionLogTransactionFixture(({ state, logAdapter, children, countElement, createTransaction }) => {
    const historicalEntries = [...state.logs];
    const historicalNodes = [...children];
    const transaction = createTransaction();
    logAdapter.add("Action 日志 1");
    logAdapter.add("Action 日志 2");
    logAdapter.add("Action 日志 3");
    assert.equal(state.logs.length, 5);
    assert.equal(children.length, 5);
    transaction.rollback();
    assert.deepEqual(state.logs, historicalEntries);
    assert.deepEqual(children, historicalNodes);
    assert.equal(state.logs[0], historicalEntries[0]);
    assert.equal(state.logs[1], historicalEntries[1]);
    assert.equal(children[0], historicalNodes[0]);
    assert.equal(children[1], historicalNodes[1]);
    assert.equal(countElement.textContent, "2 条");
    assert.equal(countElement.attributes.get("aria-label"), "共 2 条对局记录");
  });
});

test("生命周期：Action transaction commit 保留新增日志 DOM 与计数", () => {
  withActionLogTransactionFixture(({ state, logAdapter, children, countElement, createTransaction }) => {
    const transaction = createTransaction();
    logAdapter.add("提交日志 1");
    logAdapter.add("提交日志 2");
    transaction.commit();
    assert.equal(state.logs.length, 4);
    assert.equal(children.length, 4);
    assert.equal(countElement.textContent, "4 条");
  });
});

test("生命周期：Action transaction rollback 后正常追加日志不偏移", () => {
  withActionLogTransactionFixture(({ state, logAdapter, children, countElement, createTransaction }) => {
    const transaction = createTransaction();
    logAdapter.add("待回滚日志 1");
    logAdapter.add("待回滚日志 2");
    transaction.rollback();
    const nextEntry = logAdapter.add("回滚后正常日志");
    assert.equal(state.logs.length, 3);
    assert.equal(state.logs.at(-1), nextEntry);
    assert.equal(children.length, 3);
    assert.equal(countElement.textContent, "3 条");
  });
});

test("生命周期：Action transaction 多次 commit rollback 交替后日志仍一致", () => {
  withActionLogTransactionFixture(({ state, logAdapter, children, countElement, createTransaction }) => {
    const historicalEntries = [...state.logs];
    const historicalNodes = [...children];
    const firstCommit = createTransaction();
    const committedA = logAdapter.add("保留日志 A");
    firstCommit.commit();
    const committedNodeA = children.at(-1);

    const firstRollback = createTransaction();
    logAdapter.add("删除日志 A");
    logAdapter.add("删除日志 B");
    firstRollback.rollback();

    const secondCommit = createTransaction();
    const committedB = logAdapter.add("保留日志 B");
    const committedNodeB = children.at(-1);
    secondCommit.commit();

    const secondRollback = createTransaction();
    logAdapter.add("删除日志 C");
    secondRollback.rollback();

    assert.deepEqual(state.logs, [...historicalEntries, committedA, committedB]);
    assert.deepEqual(children, [...historicalNodes, committedNodeA, committedNodeB]);
    assert.equal(countElement.textContent, "4 条");
  });
});

// ---- 回合生命周期与全局额度重置 ----

test("生命周期：新全局回合只重置 global-turn reactive 额度而不重置非行动角色 actor-turn 状态", async () => {
  const a = makePlayer("actor-turn-a", 0, "dawn", "ai", 0),
    b = makePlayer("actor-turn-b", 1, "dusk", "ai", 1);
  const { game } = makeGame([a, b]);
  registerPassiveSkills(game);
  game.aiController.selectAction = async () => ({ type: "end" });
  // A 已在本回合消耗过 actor-turn 状态，并积累过 global-turn 额度。
  a.turnFlags.attackUsed = 1;
  a.turnFlags.recoverUsed = 1;
  a.turnFlags.activeSkillUseCounts.breakArmy = 1;
  a.turnFlags.activeSkillsUsed.add("breakArmy");
  a.turnFlags.skipActionPhase = true;
  a.turnFlags.coordinationTriggered = true;
  a.turnFlags.momentum = 2;
  // B 新回合开始。
  await game.takeTurn(b, game.state.gameId);
  assert.equal(a.turnFlags.attackUsed, 1);
  assert.equal(a.turnFlags.recoverUsed, 1);
  assert.equal(a.turnFlags.activeSkillUseCounts.breakArmy, 1);
  assert.equal(a.turnFlags.activeSkillsUsed.has("breakArmy"), true);
  assert.equal(a.turnFlags.skipActionPhase, true);
  // 只有 global-turn reactive 额度被刷新。
  assert.equal(a.turnFlags.coordinationTriggered, false);
  assert.equal(a.turnFlags.momentum, 0);
  assert.equal(a.turnFlags.categoriesUsed.size, 0);
});

