test("生命周期：装备替换预检取消或抛异常时新旧装备都回到执行前", async () => {
  for (const mode of ["cancel", "throw"]) {
    const source = makePlayer(`replace-${mode}-source`, 0, "dawn"),
      enemy = makePlayer(`replace-${mode}-enemy`, 1, "dusk"),
      old = instance("energyDevice"),
      next = instance("battleDevice"),
      { game }
        = makeGame([source, enemy]);
    source.equipment = old;
    source.hand.push(next);
    game.eventDispatcher.on("beforeCardMove", `test:replace-preflight-${mode}`, (event) => {
      if (event.card !== old || event.from !== "equipment") return;
      if (mode === "cancel") event.cancelled = true; else throw new Error("replacement preflight failed");
    });
    await assert.rejects(
      game.playCard(source, next, []), mode === "cancel" ? /装备牌未能进入装备区/ : /replacement preflight failed/
    );
    assert.equal(source.equipment, old);
    assertCardOnlyIn(game, old, `equipment:${source.id}`);
    assertCardOnlyIn(game, next, `hand:${source.id}`);
    assert.equal(source.statistics.cardsPlayed, 0);
  }
});

