test("生命周期：重新征召后按新阵营重新设置能量上限和无限调息", async () => {
  const verify = async (seed) => {
    let value = seed;
    const random = () => ((value = Math.imul(value, 1664525) + 1013904223 >>> 0) / 4294967296),
      ui = makeUi(),
      game = createGameApplication(ui, random);
    game.simulationMode = true;
    game.cleanupManager.delay = async () => !game.state.isDisposed;
    const candidates = game.startSelection("random");
    for (
      const player of game.state.players
    ) assert.equal(player.maxEnergy, game.teamRules.getTeamSize(player) === 2 ? 4 : 3);
    await game.confirmCharacter(candidates[0].id);
    assert.equal(game.state.players.filter((player) => player.battleTeam === "dawn").length, 2);
    assert.equal(game.state.players.filter((player) => player.battleTeam === "dusk").length, 3);
    for (const player of game.state.players) {
      assert.equal(player.maxEnergy, game.teamRules.getMaxEnergy(player));
      assert.equal(player.turnFlags.recoverLimit, null);
    }
    game.dispose();
    await game.loopPromise;
  };
  await verify(11);
  await verify(29);
});

test("生命周期：窥隙隐藏选择期间dispose会收束Promise并清理令牌", async () => {
  const shade = makePlayer("peek-dispose", 0, "dawn", "human", 3),
    target = makePlayer("peek-dispose-target", 1, "dusk");
  target.hand.push(instance("charge"), instance("harvest"));
  const { game, ui }
    = makeGame([shade, target]);
  registerPassiveSkills(game);
  let openedResolve, settle;
  const opened = new Promise((resolve) => {
    openedResolve = resolve;
  });
  ui.requestHiddenCards = () => new Promise((resolve) => {
    settle = resolve;
    openedResolve();
  });
  const baseCancel = ui.cancelPendingInteractions.bind(ui);
  ui.cancelPendingInteractions = () => {
    baseCancel();
    settle?.(null);
  };
  const pending = game.damage(shade, target, 1, { canBlock: false });
  await opened;
  assert.equal(game.hiddenCardSelection.sessions.size, 1);
  game.dispose();
  await pending;
  assert.equal(game.hiddenCardSelection.sessions.size, 0);
  assert.equal(game.hiddenCardSelection.selections.size, 0);
  assert.equal(ui.reveals.length, 0);
});

