test("生命周期：真人在自己的决斗中阵亡会在完整结算后主动结束出牌等待", async () => {
  const human = makePlayer("human", 0, "dawn", "human"),
    ally = makePlayer("ally", 1, "dawn"),
    enemy = makePlayer("enemy", 2, "dusk");
  human.hp = 1;
  const duel = instance("duel");
  human.hand.push(duel);
  enemy.hand.push(instance("assault"));
  const { game, ui }
    = makeGame([human, ally, enemy]);
  const waiting = ui.waitForHumanPlayEnd(game.state.gameId);
  assert.equal(await game.handleHumanCard(duel.id), true);
  const ended = await Promise.race(
    [waiting, new Promise((resolve) => setTimeout(() => resolve("timeout"), 50))]
  );
  assert.equal(human.alive, false);
  assert.equal(game.state.phase, "play");
  assert.equal(game.state.isGameOver, false);
  assert.equal(ended, true);
  assert.equal(ui.playEndState, null);
  assert.equal(game.pendingHumanPlayEnd, false);
});

test("生命周期：互利等待选牌时重新征召不会把 undefined 放入手牌", async () => {
  const human = makePlayer("human", 0, "dawn", "human"), enemy = makePlayer("enemy", 1, "dusk");
  const { game, ui }
    = makeGame([human, enemy]);
  game.state.deck.cards.push(instance("block"), instance("charge"));
  game.publicCardPoolWorkflow.reveal(2);
  let settleSelection = null;
  ui.requestPublicCard = () => new Promise((resolve) => {
    settleSelection = resolve;
  });
  ui.cancelPendingInteractions = () => {
    settleSelection?.(undefined);
  };
  const drafting = game.publicCardPoolWorkflow.draft(human);
  await Promise.resolve();
  game.dispose();
  assert.equal(await drafting, false);
  assert.deepEqual(human.hand, []);
  assert.equal(human.hand.includes(undefined), false);
  assert.equal(game.state.publicCardPool.length, 0);
});

