test("集成：掠夺装备收入手牌且不会替换或弃置使用者旧装备", async () => {
  const actor = makePlayer("actor", 0, "dawn", "human"),
    target = makePlayer("target", 1, "dusk"),
    use = instance("plunder");
  const old = instance("barrierDevice"), moved = instance("energyDevice");
  actor.equipment = old;
  actor.hand.push(use);
  target.equipment = moved;
  const { game }
    = makeGame([actor, target]);
  const selection = game.hiddenCardSelection.createHiddenSelection(target);
  await game.playCard(
    actor,
    use,
    [target],
    {
      zone: "equipment",
      selectionKind: "equipment",
      definitionId: moved.definitionId,
      equipmentCardId: moved.id,
      selectionId: selection.selectionId
    }
  );
  assert.equal(actor.equipment, old);
  assert.ok(actor.hand.includes(moved));
  assert.ok(!game.state.deck.discardPile.includes(old));
  assert.equal(target.equipment, null);
  assert.equal(await game.playCard(actor, moved, []), true);
  assert.equal(actor.equipment, moved);
  assert.ok(game.state.deck.discardPile.includes(old));
});

