test("集成：调律师转移把来源与接收者都作为有效目标并只触发一次协调", async () => {
  const tuner = makePlayer("tuner", 0, "dawn", "ai", 7),
    enemy = makePlayer("enemy", 1, "dusk"),
    ally = makePlayer("ally", 2, "dawn");
  const { game }
    = makeGame([tuner, enemy, ally]);
  registerPassiveSkills(game);
  game.state.deck.cards.push(instance("charge"));
  let usedEvent = null;
  game.eventDispatcher.on("cardUsed", "test:successful-transfer", (event) => {
    usedEvent = event;
  });
  const use = instance("transfer"), moved = instance("block");
  tuner.hand.push(use);
  enemy.hand.push(moved);
  enemy.bumpHandVersion(TEST_VERSION_STATE);
  const hidden = game.hiddenCardSelection.createHiddenSelection(enemy);
  await game.playCard(
    tuner,
    use,
    [],
    {
      sourceId: enemy.id,
      receiverId: ally.id,
      zone: "hand",
      tokens: [hidden.tokens[0].token],
      selectionId: hidden.selectionId
    }
  );
  assert.ok(ally.hand.includes(moved));
  assert.equal(tuner.turnFlags.coordinationTriggered, true);
  assert.equal(tuner.hand.length, 1);
  assert.equal(usedEvent.cancelled, false);
  assert.equal(usedEvent.resolved, true);
  assert.deepEqual(usedEvent.effectiveTargets, [enemy, ally]);
});

